  },
  {
    "id": "c64c60e5-2efd-5044-acdc-44c2d3c1d905", "type": "c2_mor_combinacions", "sort_order": 6,
    "title": "Combinacions pronominals: restriccions i ternàries", "name": "Orde i forma de les combinacions binàries i ternàries, restriccions amb en i la preposició de, apòstrofs i guionets",
    "content": "L'orde fix i la forma de les combinacions de pronoms febles, les binàries difícils (li'n, l'hi, els en, n'hi), les ternàries (menjar-se-me-la, se me n'ha anat) i les restriccions de les combinacions amb en i la preposició partitiva (En cuinaran uns quants de moniato) (3.2.2).", "icon": "🔗", "color": "#E0F7FA",
    "exercises": [
      {"q": "Escriu la combinació de «me» + «lo» davant de verb començat per consonant: «Tens el llibre? ___ portaràs demà?»", "a": ["me'l"], "e": "Me + lo davant de consonant: me'l (Me'l podries portar). GNV 22.4.2."},
      {"q": "Escriu la combinació de «li» + «lo» davant de verb començat per consonant: «Ja ___ portaré demà.» (el paquet, a ella)", "a": ["li'l"], "e": "Li + lo davant de consonant: li'l portaré; davant de vocal, li l'he portat. GNV 22.4.2.d."},
      {"q": "Escriu els pronoms que falten: «___ vaig anar a les tres de la nit.» (me + ne, davant de consonant)", "a": ["me'n", "me’n"], "e": "Me + ne davant de verb començat per consonant: me'n vaig anar (ne lexicalitzat amb anar-se'n). GNV 22.4.2 i 23.4.1."},
      {"q": "Escriu la forma completa de l'imperatiu «emportem» amb els pronoms nos i els: «___ ja!»", "a": ["emportem-nos-els"], "e": "Quan el primer pronom acaba en s, el segon pren la forma reforçada: Emportem-nos-els. GNV 22.4.2.f."},
      {"q": "Escriu la combinació de datiu plural + acusatiu plural: «___ vam tornar» (els diners, als veïns)", "a": ["els els"], "e": "Els + els: Els els vam tornar; el segon pronom pren la forma reforçada perquè el primer acaba en s. GNV 22.4.2.f."},
      {"q": "Escriu la combinació de datiu plural + ne: «No ___ vull dir res.» (a ells + en)", "a": ["els en"], "e": "Els + ne: No els en vull dir res; enclític: No vull dir-los-en res. GNV 22.4.2.f."},
      {"q": "Escriu la combinació que falta: «No ___ va acudir preguntar per tu.» (se + me)", "a": ["se'm"], "e": "Se + me: se'm (No se'm va acudir). El pronom se va primer; l'apòstrof va tan a la dreta com siga possible. GNV 22.4.2."},
      {"q": "Escriu els pronoms que falten: «Ja ___ ha anat el cap.» (se + me + ne, combinació ternària)", "a": ["se me n'", "se me n’"], "e": "Combinació ternària: ordre fix se - me - ne, amb la forma plena davant i ne elidit: se me n'ha anat. GNV 22.4.1 i 22.4.2."},
      {"q": "Escriu la combinació: «Només ___ havia tres.» (ne + hi)", "a": ["n'hi"], "e": "Ne + hi: n'hi havia, n'hi ha. L'orde és sempre ne - hi. GNV 22.4.1 i 22.4.2."},
      {"q": "Quina és la frase correcta?", "o": ["Me la van regalar.", "Em la van regalar.", "Me'la van regalar."], "e": "Els pronoms em, et i es adopten les formes plenes (me, te, se) quan són el primer d'una combinació proclítica: Me la van regalar. GNV 22.4.2.e."},
      {"q": "Quina és la frase correcta?", "o": ["Quan te n'aniràs a Xàtiva?", "Quan et n'aniràs a Xàtiva?", "Quan t'en aniràs a Xàtiva?"], "e": "Te pren la forma plena davant de ne, i ne s'elidix davant de vocal: te n'aniràs. GNV 22.4.2.e."},
      {"q": "Quina és la forma admesa en registres formals?", "o": ["Se m'ha fet tard.", "Me s'ha fet tard.", "Em s'ha fet tard."], "e": "La posposició de se (Me s'ha fet tard) és habitual en la llengua oral, però no és acceptable en registres formals: l'orde és se - me. GNV 22.4.2.a."},
      {"q": "Quina és la frase correcta?", "o": ["Quan m'ho diràs?", "Quan me ho diràs?", "Quan em ho diràs?"], "e": "Els pronoms em, et i es adopten la forma elidida seguits de ho o hi: m'ho, t'ho, s'hi. GNV 22.4.2.e."},
      {"q": "Quina és la frase correcta?", "o": ["No s'hi troba, amb un vestit tan modern.", "No se hi troba, amb un vestit tan modern.", "No es hi troba, amb un vestit tan modern."], "e": "Se + hi dona s'hi (forma elidida davant de hi). GNV 22.4.2.e."},
      {"q": "Quina és la frase correcta?", "o": ["Si vols, l'en farem partícip.", "Si vols, el ne farem partícip.", "Si vols, le'n farem partícip."], "e": "Lo + ne pren la forma elidida l'en, ja que si no donaria la forma inexistent le. GNV 22.4.2.d."},
      {"q": "Quina és la frase correcta?", "o": ["Compra-te-la demà.", "Compra-tela demà.", "Compra't-la demà."], "e": "En posició enclítica els pronoms van lligats al verb i entre ells amb guionets: Compra-te-la. GNV 22.4.2.c."},
      {"q": "Quina és la frase correcta?", "o": ["Ves-te'n ja!", "Ves-ten ja!", "Ves-te-ne ja!"], "e": "Te + ne enclític: Ves-te'n. L'apòstrof marca l'elisió de ne. GNV 22.4.2.c."},
      {"q": "Quina és la frase correcta?", "o": ["No vols dir-m'ho?", "No vols dir-me-ho?", "No vols dir-mho?"], "e": "Me + ho enclític: dir-m'ho (forma elidida m'ho darrere de verb). GNV 22.4.2.c."},
      {"q": "Quina és la forma correcta de la combinació enclítica de «li» i «la»?", "o": ["Dona-li-la.", "Dona-la-li.", "Dona-lila."], "e": "L'orde dels pronoms és fix: el datiu (li) va abans de l'acusatiu (la), també en posició enclítica: Dona-li-la. GNV 22.4.2.a."},
      {"q": "Quin és l'orde fix dels pronoms febles?", "o": ["se - te/vos - me/nos - li/los - lo/la/los/les - ne - hi", "lo/la - li - me - te - se - ne - hi", "me/te - se - li - hi - ne - lo/la"], "e": "L'orde és fix i independent de la posició proclítica o enclítica, i no es pot invertir. GNV 22.4.1 (taula 22.10)."},
      {"q": "Quina combinació és impossible segons l'orde fix?", "o": ["Dos pronoms de la mateixa columna, com me i te", "me + ho", "se + me"], "e": "Són possibles les combinacions de pronoms de columnes diferents, però no els d'una mateixa columna. GNV 22.4.1."},
      {"q": "Quina és la frase correcta?", "o": ["Ja se n'ha anat.", "Ja s'en ha anat.", "Ja sen ha anat."], "e": "En les combinacions amb elisió, l'apòstrof es col·loca tan a la dreta com siga possible: se n'ha anat, però se'n va anar. GNV 22.4.2.d."},
      {"q": "Quina és la frase correcta?", "o": ["Ja se'n va anar.", "Ja s'en va anar.", "Ja se n'va anar."], "e": "Davant de verb començat per consonant, ne es reduïx i s'apostrofa al pronom anterior: se'n va anar. GNV 22.4.2.d."},
      {"q": "Quina és la frase correcta?", "o": ["Li'l portaré demà.", "Li el portaré demà.", "Li l'portaré demà."], "e": "Li + lo davant de consonant: li'l; davant de vocal: No li l'he portat. GNV 22.4.2.d."},
      {"q": "Quina és la frase correcta?", "o": ["Ens els portaran demà.", "Ens los portaran demà.", "Nos els portaran demà."], "e": "Nos + los davant de consonant: ens els. GNV 22.4.2 (taula 22.11)."},
      {"q": "Quina és la frase correcta?", "o": ["Els la portaré demà.", "Los la portaré demà.", "Els li portaré demà."], "e": "Els (datiu plural) + la: els la. Els pronoms de la mateixa columna no es poden combinar (els li). GNV 22.4.2 i 22.4.1."},
      {"q": "Quina és la frase correcta?", "o": ["Com li agraden les novel·les policíaques, li'n vaig regalar un parell.", "Com li agraden les novel·les policíaques, li en vaig regalar un parell.", "Com li agraden les novel·les policíaques, lin vaig regalar un parell."], "e": "Li + ne davant de consonant: li'n. GNV 22.4.2 i 23.4.1.a."},
      {"q": "Quina és la frase correcta?", "o": ["L'arròs està molt bo, però no me'n poses més.", "L'arròs està molt bo, però no m'en poses més.", "L'arròs està molt bo, però no me en poses més."], "e": "Me + ne davant de consonant: me'n. GNV 22.4.2 i 23.4.1.a."},
      {"q": "Quina és la frase correcta?", "o": ["Si no t'agraden, me'ls tornes.", "Si no t'agraden, em els tornes.", "Si no t'agraden, me los tornes."], "e": "Me + los: me'ls (Me'ls tornes). GNV 22.4.2 i 23.2.2."},
      {"q": "En els parlars més septentrionals s'hi diu «L'hi he donat». Quina és la combinació general equivalent?", "o": ["Li l'he donat", "Se l'he donat", "Els l'he donat"], "e": "En alguns parlars li adopta la forma hi i es posposa a l'acusatiu (l'hi he donat), però la combinació general és li l'he donat; se l'he donat és un calc del castellà. GNV 22.4.2.c."},
      {"q": "A quin fenomen respon l'antiga combinació «la hi donà» (per «la li donà»)?", "o": ["Dissimilació de la consonant lateral de li", "Assimilació del pronom hi", "Analogia amb el castellà"], "e": "La combinació «acusatiu + datiu hi» respon a l'orde antic dels pronoms i a la dissimilació de consonant lateral (la li → la hi). GNV 22.4.2."},
      {"q": "Què passa amb la vocal de suport en «Els [e] la portaré demà» o «Vos [e] n'aneu ja»?", "o": ["És acceptable en l'oral, però no s'escriu", "S'ha d'escriure sempre en la llengua formal", "És obligatòria en l'estàndard"], "e": "La vocal de suport és acceptable en l'àmbit oral dels parlars en què és pròpia, però no té reflex ni en els registres formals ni en l'escriptura. GNV 22.4.2.b."},
      {"q": "Completa: «Les gàbies que teniu les trobe menudes. ¿En teniu ___ més grans?»", "o": ["de", "dels", "per"], "e": "Quan el nucli es pronominalitza per ne, la preposició de introduïx els complements no pronominalitzats (adjectius): en teniu de més grans. GNV 26.3.3.1."},
      {"q": "Completa: «No vos emporteu tots els llibres, que n'hi ha ___ meus.»", "o": ["de", "dels", "als"], "e": "Amb ne, la preposició de introduïx el complement no pronominalitzat (un possessiu): n'hi ha de meus. GNV 26.3.3.1."},
      {"q": "Completa: «N'hi havia moltes ___ picades.»", "o": ["de", "per", "amb"], "e": "Quan el nucli nominal es pronominalitza per ne, apareix la preposició de davant del participi: n'hi havia moltes de picades. GNV 26.3.3.1."},
      {"q": "Completa: «Em va recomanar molts llibres antics i uns quants ___ moderns.»", "o": ["de", "dels", "a"], "e": "Quan el nom s'elidix i hi ha un quantificador (uns quants), s'usa de: uns quants de moderns. Alternativa: uns quants llibres moderns. GNV 26.3.3.1."},
      {"q": "Quina frase és correcta per a «Cuinaran pastissos de moniato; n'hi ha uns quants»?", "o": ["En cuinaran uns quants de moniato.", "En cuinaran uns quants moniato.", "En cuinaran uns quants del moniato."], "e": "Si el nucli (pastissos) es pronominalitza amb en, el complement no pronominalitzat va introduït per de: En cuinaran uns quants de moniato. GNV 26.3.3.1 i 23.4.1.a."},
      {"q": "Quina frase és correcta?", "o": ["Me n'he menjat tres de roges.", "Me n'he menjat tres roges.", "Me les he menjat tres de roges."], "e": "Ne pronominalitza el nucli, però no els quantificadors; el complement no pronominalitzat porta de: me n'he menjat tres de roges. GNV 23.4.1.a."},
      {"q": "Quina és la frase correcta?", "o": ["Se me n'ha anat el cap.", "Me se n'ha anat el cap.", "Se'm n'ha anat el cap."], "e": "En les combinacions ternàries l'orde és fix (se - me - ne) i l'apòstrof va tan a la dreta com siga possible: se me n'ha anat. GNV 22.4.1 i 22.4.2.d."},
      {"q": "Quina és la forma correcta de l'infinitiu amb tres pronoms («menjar» + se + me + la)?", "o": ["menjar-se-me-la", "menjar-me-se-la", "menjar-se'm-la"], "e": "Combinació ternària enclítica: ordre fix se - me - la i guionets entre els pronoms: menjar-se-me-la. GNV 22.4.1 i 22.4.2.c."},
      {"q": "Quina és la frase correcta?", "o": ["Vam tornar-los-els.", "Vam tornar-els-los.", "Vam tornar-los-los."], "e": "Els pronoms de la mateixa columna no es poden combinar; l'orde dels datius i acusatius és fix, i el segon pren la forma reforçada: tornar-los-els. GNV 22.4.2.f."},
      {"q": "Quina és la frase correcta?", "o": ["Posa-me'n una miqueta.", "Posa-me-ne una miqueta.", "Posa'm-ne una miqueta."], "e": "Me + ne darrere de verb acabat en vocal: -me'n (posa-me'n). GNV 22.4.2 i 23.4.1.a."},
      {"q": "Quina és la frase correcta?", "o": ["Mira-te'l bé.", "Mira-te-lo bé.", "Mira't-lo bé."], "e": "Te + lo enclític: -te'l (mira-te'l), amb apòstrof, com me'l. GNV 22.4.2 (taula 22.11)."},
      {"q": "Quina és la frase correcta?", "o": ["Ens hi van portar en cotxe.", "Nos hi van portar en cotxe.", "Ens-hi van portar en cotxe."], "e": "Nos + hi davant de consonant: ens hi. En posició proclítica els pronoms s'escriuen separats. GNV 22.4.2.b."},
      {"q": "Escriu la combinació que falta: «Ja ___ pensava, que arribaria tard.» (se + ho)", "a": ["s'ho"], "e": "Se + ho: s'ho (s'ho pensava). GNV 22.4.2 (taula 22.11)."}
    ]
  },
  {
    "id": "94ad596c-99ce-5d8d-b0b9-0f71c2422b0a", "type": "c2_mor_relatius", "sort_order": 7,
    "title": "Relatius, interrogatius i exclamatius", "name": "Supressió de la preposició, que/què/qui/el qual, usos redundants del pronom feble, n'hi ha que, cosa que, interrogatius reforçats i exclamatius",
    "content": "El relatiu sense preposició (el dia que vaig nàixer), el relatiu amb preposició (què, qui, el qual), les construccions particulars (n'hi ha que, hi ha qui, cosa que, la qual cosa), els usos redundants del pronom feble en relatives, els interrogatius reforçats (què dimonis fas?) i els exclamatius (3.2.2).", "icon": "🔎", "color": "#FFF8E1",
    "exercises": [
      {"q": "Completa: «Vine el dia ___ pugues.»", "o": ["que", "quan", "el qual"], "e": "Amb un antecedent temporal explícit s'usa que (o en què, en el qual), no quan: vine el dia que pugues. GNV 24.3.3.a."},
      {"q": "Quina de les formes següents NO és adequada en «Això va passar l'any ___ va faltar el pare»?", "o": ["quan", "que", "en què"], "e": "Amb antecedent explícit s'empra que i, precedit de en, què o el qual (l'any que / en què / en el qual); quan s'usa sense antecedent. GNV 24.3.3.a."},
      {"q": "Escriu el relatiu que falta: «Recorde el dia ___ vaig nàixer.»", "a": ["que"], "e": "La preposició (en) se suprimix: el dia que vaig nàixer, com el dia que vindràs. GNV 24.3.3.a."},
      {"q": "Quina és la combinació NO acceptable?", "o": ["De la manera quan t'ha contestat, em pense que ja ho sap.", "De la manera com t'ha contestat, em pense que ja ho sap.", "De la manera en què t'ha contestat, em pense que ja ho sap."], "e": "En les relatives especificatives, com només pot anar precedit de manera o forma; també és possible que, en què o en la qual. GNV 24.3.3.c."},
      {"q": "Completa: «He deixat el cabàs ___ m'havies dit.»", "o": ["on", "quan", "que"], "e": "El relatiu locatiu on pot usar-se amb antecedent o sense: He deixat el cabàs on m'havies dit. GNV 24.3.3.b."},
      {"q": "Quina frase és preferible en registres formals?", "o": ["Esta és la carpeta on guarde els documents.", "Esta és la carpeta a on guarde els documents.", "Esta és la carpeta que on guarde els documents."], "e": "Amb valor de pura localització on pot dur la preposició a o no, però en els registres formals es preferix sense preposició. GNV 24.3.3.b."},
      {"q": "Completa: «Vam arribar a una ciutat ___ no tenia cotxe ningú.»", "o": ["en què", "en la que", "en el que"], "e": "El que només s'admet en relatives sense antecedent; amb antecedent, els registres formals usen què o el qual precedits de preposició, o on: en què, en la qual, on. GNV 24.3.2.a."},
      {"q": "Completa: «El tema ___ parles no m'interessa.»", "o": ["de què", "del que", "de que"], "e": "Amb antecedent i preposició s'usa què o el qual: el tema de què parles. GNV 24.3.2.a i d."},
      {"q": "Completa: «La xica ___ has escrit ara ix amb un altre xic.»", "o": ["a qui", "a què", "a la que"], "e": "Qui s'usa per a persones precedit de preposició àtona (a, en, de, amb, per): la xica a qui has escrit. GNV 24.3.2.d."},
      {"q": "Completa: «Ell és la persona ___ més confie.»", "o": ["en qui", "en què", "en la que"], "e": "Per a persones s'usa qui amb preposició àtona: la persona en qui més confie. GNV 24.3.2.d."},
      {"q": "Completa: «Els motius ___ ha dimitit són evidents.»", "o": ["per què", "perquè", "pel que"], "e": "Amb preposició àtona per, el relatiu és què (amb accent) en escriptura separada: els motius per què ha dimitit. GNV 24.3.2.d."},
      {"q": "Completa: «És una malaltia ___ hui en dia encara no podem lluitar.»", "o": ["contra la qual", "contra què", "contra qui"], "e": "Què i qui només admeten les preposicions àtones a, en, de, amb i per; amb preposicions tòniques (contra) cal el qual: contra la qual. GNV 24.3.2.d."},
      {"q": "Quin relatiu NO pot usar-se en «Aquell polític, ___ no té cap escrúpol, ara diu que sí que firmarà»?", "o": ["qui", "que", "el qual"], "e": "En les explicatives, que pot alternar amb el qual, però no amb qui. GNV 24.3.2.b."},
      {"q": "Completa: «Va gratificar el client ___ havia tacat.»", "o": ["que", "el qual", "qui"], "e": "El relatiu el qual no pot substituir que en una relativa especificativa. GNV 24.3.2.c."},
      {"q": "Escriu el relatiu que falta: «___ t'ho haja dit, t'ha amagat una part de la veritat.»", "e": "En relatives sense antecedent, quan es referix a una persona i no va precedit de determinant, s'usa qui. GNV 24.3.2.e.", "a": ["qui"]},
      {"q": "Quina és la forma més formal i tradicional?", "o": ["De tots els jugadors que has vist, tria el qui més t'agrade.", "De tots els jugadors que has vist, tria el que més t'agrade.", "De tots els jugadors que has vist, tria el qual més t'agrade."], "e": "Amb determinant són possibles el qui i el que, però la primera és la més formal i tradicional. GNV 24.3.2.e."},
      {"q": "Escriu el relatiu que falta: «___ no vullga pols que no vaja a l'era.»", "a": ["qui"], "e": "Qui s'usa sense antecedent i sense determinant: Qui no vullga pols que no vaja a l'era. GNV 24.2 (taula 24.1)."},
      {"q": "Completa: «És un jugador l'habilitat ___ és dubtosa.»", "o": ["del qual", "que", "de qui"], "e": "El qual amb valor possessiu precedit de de (complement del nom) és propi dels registres formals: l'habilitat del qual. GNV 24.3.2.f."},
      {"q": "Completa: «He anat a uns quants bancs, els caixers ___ no funcionen.»", "o": ["dels quals", "dels que", "que"], "e": "Valor possessiu amb el qual: els caixers dels quals. GNV 24.3.2.f."},
      {"q": "Escriu el relatiu que falta: «Tinc un amic el pare ___ és obrer.»", "a": ["del qual"], "e": "Construcció sintètica (formal) amb valor possessiu: el pare del qual. La forma analítica és Tinc un amic que el seu pare és obrer. GNV 24.3.4."},
      {"q": "Quina frase és adequada en registres formals?", "o": ["És un home a qui no lluïx la faena.", "És un home que no li lluïx la faena.", "És un home a qui no li lluïx la faena."], "e": "Les construccions de relatiu analítiques o amb pronom feble redundant són pròpies dels registres informals. GNV 24.3.4."},
      {"q": "Quina frase és adequada en registres formals?", "o": ["Tinc un amic el pare del qual és obrer.", "Tinc un amic que el seu pare és obrer.", "Tinc un amic que son pare és obrer."], "e": "La construcció sintètica amb el pare del qual és la pròpia dels registres formals. GNV 24.3.4."},
      {"q": "Quina frase és adequada en registres formals?", "o": ["És un poble on hi ha molta gent.", "És un poble que hi ha molta gent.", "És un poble que on hi ha molta gent."], "e": "Amb locatiu, la construcció sintètica és on hi ha; és un poble que hi ha és analítica i informal. GNV 24.3.4."},
      {"q": "Quina frase és adequada en registres formals?", "o": ["És un tema que no domine.", "És un tema que no el domine.", "És un tema el qual no el domine."], "e": "El pronom feble redundant en les relatives (que no el domine) no és propi dels registres formals. GNV 24.3.4 (observació)."},
      {"q": "Quina frase és adequada en registres formals?", "o": ["La xica a qui he demanat l'hora.", "La xica a qui li he demanat l'hora.", "La xica que li he demanat l'hora."], "e": "L'ús pleonàstic del pronom datiu en relatives (a qui li he demanat) s'evita en registres formals. GNV 23.2.2.2."},
      {"q": "Completa: «L'Ajuntament no està disposat a fer res, ___ ens té a tots indignats.»", "o": ["cosa que", "lo que", "lo qual"], "e": "Les relatives neutres usen un substantiu genèric davant del relatiu: cosa que (o la qual cosa). GNV 24.3.1."},
      {"q": "Completa: «El president no va admetre el torn de rèplica, ___ va ser molt criticada.»", "o": ["la qual cosa", "lo qual", "la que"], "e": "El qual pot actuar com a determinant d'un substantiu genèric que es referix a l'oració anterior: la qual cosa. GNV 24.3.1."},
      {"q": "Completa: «Ahir férem un gran esforç, ___ ens permet ara anar més relaxats.»", "o": ["cosa que", "lo qual", "lo que"], "e": "Lo qual és un calc del castellà; s'hi usa cosa que o la qual cosa. GVB 19.5.2."},
      {"q": "Completa: «El concert va costar trenta mil euros, ___ que haurà d'assumir la Diputació.»", "o": ["quantitat", "cosa", "quant"], "e": "En les explicatives l'antecedent (o un sinònim) pot repetir-se davant de que: quantitat que. GNV 24.3.1.a."},
      {"q": "Escriu la paraula que falta: «Ha hagut de pagar sis-cents euros, la ___ suma és insignificant per a este empresari.»", "a": ["qual"], "e": "El relatiu el qual pot actuar com a determinant de l'antecedent repetit: la qual suma. GNV 24.3.1.b."},
      {"q": "Escriu el relatiu que falta: «Vine ___ pugues.»", "e": "El relatiu temporal quan s'usa sense antecedent: Vine quan pugues. GNV 24.3.3.a.", "a": ["quan"]},
      {"q": "Escriu el relatiu que falta: «Fes-ho ___ millor pugues i sàpies.»", "e": "El relatiu de manera com pot usar-se sense antecedent. GNV 24.3.3.c.", "a": ["com"]},
      {"q": "Completa: «Ves-te'n ___ vullgues.»", "o": ["allà on", "allà que", "allà quan"], "e": "El relatiu on pot usar-se sense antecedent explícit, sovint amb allà: ves-te'n allà on vullgues. GNV 24.3.3.b."},
      {"q": "Escriu el relatiu que falta: «Hem visitat la ciutat ___ vas nàixer.»", "a": ["on"], "e": "On amb antecedent locatiu explícit: la ciutat on vas nàixer. GNV 24.3.3.b."},
      {"q": "Completa: «Entre els integrants del grup, ___ que tenen idees estrafolàries.»", "o": ["n'hi ha", "hi ha", "en hi ha"], "e": "N'hi ha que...: ne pronominalitza el partitiu (alguns dels integrants) i hi és l'existencial: n'hi ha que tenen idees estrafolàries. GNV 26.5.3."},
      {"q": "Quina frase és correcta?", "o": ["Hi ha qui opina que el president introduirà canvis.", "Hi han qui opinen que el president introduirà canvis.", "Hi ha que opina que el president introduirà canvis."], "e": "Hi ha qui + verb és una construcció impersonal que substituïx el molt formal hom: Hi ha qui opina que... GVB 24.3.5."},
      {"q": "Quina és la forma correcta de l'interrogatiu reforçat?", "o": ["Què dimonis fas?", "Que dimonis fas?", "Quin dimonis fas?"], "e": "Els pronoms interrogatius es reforcen amb substantius interjectius (dimonis, diables, botons); què du accent, a diferència del quantificador que. GNV 25.2.3."},
      {"q": "Escriu el substantiu interjectiu que falta per a reforçar l'interrogatiu: «Què ___ fas ací?» (una de les formes acceptades)", "a": ["dimonis", "diables"], "e": "Els interrogatius poden reforçar-se amb diable, dimoni, recordons, botons...: Què dimonis fas? GNV 25.2.3."},
      {"q": "Completa: «M'han preguntat ___ maletes duc.»", "o": ["quantes", "quant", "quin"], "e": "En les interrogatives indirectes parcials, quant concorda amb el substantiu: quantes maletes. GNV 25.3.a."},
      {"q": "Quina és la frase correcta?", "o": ["Quina calor més insuportable!", "Que calor més insuportable!", "Quant calor més insuportable!"], "e": "Quin (amb valor qualitatiu) modifica un substantiu; que només pot quantificar adjectius o adverbis. GNV 25.4.1."},
      {"q": "Quina és la frase correcta?", "o": ["Que bé que parla!", "Quin bé que parla!", "Quant bé que parla!"], "e": "L'exclamatiu que modifica un adjectiu o un adverbi: Que bé que parla! GNV 25.4.1."},
      {"q": "Quina frase NO és correcta?", "o": ["Que calor que fa!", "Quina calor que fa!", "Quanta calor que fa!"], "e": "L'exclamatiu que només modifica adjectius o adverbis; davant d'un substantiu s'usa quin o quant: Quina calor que fa! GNV 25.4.1.c."},
      {"q": "Quina és la frase correcta?", "o": ["Quants llibres que té Lluís!", "Quants llibres que Lluís té!", "Quants llibres Lluís que té!"], "e": "Si l'exclamatiu no incidix sobre el subjecte, el subjecte se situa al final i apareix un que àton: Quants llibres que té Lluís! GNV 25.4.1."},
      {"q": "Escriu la preposició que falta: «Quant ___ sucre t'has posat!»", "e": "L'exclamatiu quant amb valor quantitatiu duu de davant d'un nom de matèria: Quant de sucre! GNV 25.4.1.b.", "a": ["de"]},
      {"q": "Completa: «Com és ___ verderol!»", "o": ["de", "en", "amb"], "e": "L'exclamatiu com pot explicitar la propietat per mitjà d'un adjectiu precedit de de: Com és de verderol! GNV 25.4.2."},
      {"q": "Completa: «Quanta ___ ha acudit a la presentació!»", "o": ["gent", "gents", "gente"], "e": "Quant amb valor quantitatiu concorda amb el nom: Quanta gent ha acudit! (davant de nom de matèria: quant de sucre). GNV 25.4.1.b."}
    ]
  },
  {
    "id": "94a9781c-a16b-5053-b24a-89129cbef57b", "type": "c2_mor_numerals", "sort_order": 8,
    "title": "Numerals: fraccions, col·lectius i prefixos cults", "name": "Fraccions, col·lectius (dotzena, lustre, grossa, tern, qüern), el número u i prefixos numerals cultes (hemi-, semi-, mono-, bi-, tri-, quadri-)",
    "content": "La lectura i l'escriptura de fraccions, els col·lectius i els tradicionals (grossa, tern, qüern, lustre), les interferències (el número u de la classificació), els prefixos cults numerals (hemi-, semi-, mono-, bi-, tri-, quadri-) i les formes compostes (quadrimestre, bienni, quinquenni) (3.2.2).", "icon": "🔢", "color": "#E8EAF6",
    "exercises": [
      {"q": "Completa amb el partitiu de ½: «Ha menjat ___ pizza i la resta la guardarem per al sopar.»", "o": ["mitja", "mig", "meitat"], "e": "El partitiu de ½ és mig (mitja en femení): mitja pizza. Com a substantiu, la mitat o la meitat. GNV 18.5."},
      {"q": "Escriu el substantiu que designa ½ (una de les dos formes admeses): «La ___ dels ingressos es destina a la rehabilitació.»", "a": ["mitat", "meitat"], "e": "Per a ½ s'usa el substantiu mitat (o meitat): la mitat dels ingressos. GNV 18.5 i DNV."},
      {"q": "Com es llig la fracció 2/3?", "o": ["dos terços", "dos terces", "dos terçs"], "e": "Els partitius tenen la forma dels ordinals, amb la excepció de ½ (mig/mitja) i ⅓ (terç, terços, terça, terces): dos terços. GNV 18.5 i DNV."},
      {"q": "Escriu en lletra el plural masculí del partitiu de ⅓: «Dos ___ del pressupost.»", "a": ["terços"], "e": "Terç fa terços en plural masculí (femení: terces): dos terços, 2/3. GNV 18.5 i DNV."},
      {"q": "Com es llig la fracció 3/4?", "o": ["tres quarts", "tres quartos", "tres quartons"], "e": "El partitiu de 1/4 és quart; en plural, quarts: tres quarts. GNV 18.5."},
      {"q": "Com es llig la fracció 5/6?", "o": ["cinc sisens", "cinc sisé", "cinc sisos"], "e": "Els partitius tenen la forma dels ordinals, en plural: cinc sisens (sisé, sisens). GNV 18.5 i 18.4.1."},
      {"q": "Quina és la forma culta de l'ordinal «10é»?", "o": ["dècim", "desen", "dècimé"], "e": "Els ordinals tenen formes cultes i patrimonials: dècim / dècima (cultes) i desé / desena (patrimonials). GNV 18.4.1 i 18.4.2.a."},
      {"q": "Quina és la frase correcta?", "o": ["Una tercera part dels ingressos", "Un tercera part dels ingressos", "Una tercer part dels ingressos"], "e": "Els partitius es reforcen amb el substantiu part, que és femení: una quarta part, una tercera part dels ingressos. GNV 18.5."},
      {"q": "Quina és la forma correcta en els registres formals?", "o": ["la primera volta", "la primer volta", "la primere volta"], "e": "Primer i segon presenten sempre variació de gènere i nombre; les formes sense variació (la primer volta) no són acceptables en els registres formals. GNV 18.4.2.c."},
      {"q": "Quina és la forma correcta?", "o": ["el número u de la classificació", "el número un de la classificació", "el número una de la classificació"], "e": "Quan el cardinal fa referència al nom del número o no modifica un substantiu s'usa u: el número u. GNV 18.3.2.a."},
      {"q": "Escriu el cardinal que falta: «L'equip ocupa el número ___ de la classificació.»", "a": ["u"], "e": "Referit al nom del número s'usa la forma u (no un): el número u. GNV 18.3.2.a."},
      {"q": "Completa: «—Ja han marcat algun gol? —Sí, van dos a ___.»", "o": ["u", "un", "una"], "e": "El cardinal u s'usa quan no funciona com a modificador d'un substantiu: dos a u, u a u. GNV 18.3.2.a."},
      {"q": "Quina és la forma correcta?", "o": ["tres-centes persones", "tres-cents persones", "trescentes persones"], "e": "Cent adopta el plural cents (masculí) i centes (femení): tres-centes persones. GNV 18.3.2.b."},
      {"q": "Quina frase és correcta en registres formals?", "o": ["Dos llibres i dues llibretes", "Dos llibres i dos llibretes", "Dues llibres i dues llibretes"], "e": "El cardinal dos admet la variació de gènere en els registres formals: dues llibretes. GNV 18.3.2.b."},
      {"q": "Quina és la forma correcta?", "o": ["vint-i-dos", "vint-dos", "vintidós"], "e": "En els cardinals compostos de la vintena s'intercala la conjunció i amb guionets: vint-i-dos. GNV 18.3.2.d."},
      {"q": "Escriu el plural de «dos» com a substantiu (els números): «Els ___ i els tresos estan ratllats.»", "a": ["dosos"], "e": "Els cardinals només admeten plural quan s'usen com a substantius: els dosos, els tresos, dos sisos. GNV 18.3.2.c."},
      {"q": "Completa: «Només té ___ ulleres, no tres.»", "o": ["unes", "uns", "una"], "e": "El cardinal un adopta el plural amb substantius pluralia tantum: unes ulleres, unes tisores. GNV 18.3.2.c."},
      {"q": "Quina és la forma correcta?", "o": ["l'u de maig", "el u de maig", "l'un de maig"], "e": "El primer dia d'un mes s'expressa amb el cardinal u, amb apostrofació: l'u de maig (o l'1 de maig). GNV 18.3.2.e i 18.4.2.e."},
      {"q": "Quin període designa el col·lectiu «lustre»?", "o": ["Cinc anys", "Deu anys", "Quatre anys"], "e": "Lustre és un període de cinc anys (com quinquenni). DNV."},
      {"q": "Escriu un col·lectiu que designe un període de cinc anys (una de les formes acceptades).", "a": ["lustre", "quinquenni"], "e": "Lustre i quinquenni designen un període de cinc anys. DNV i GNV 18.7."},
      {"q": "Quantes unitats designa la «grossa» com a mesura?", "o": ["Dotze dotzenes (144)", "Dotze", "Cent"], "e": "Grossa és, en metrologia, dotze dotzenes. DNV."},
      {"q": "Quantes unitats té una «dotzena de frare»?", "o": ["Tretze", "Dotze", "Catorze"], "e": "Dotzena de frare és el conjunt de tretze unitats. DNV."},
      {"q": "Què designa «quinzena» en «la primera quinzena d'agost»?", "o": ["Un espai de quinze dies", "Un grup de quinze setmanes", "Un període de quinze mesos"], "e": "Quinzena és el grup de quinze unitats i també l'espai de quinze dies. DNV."},
      {"q": "Quin col·lectiu designa un conjunt de tres coses d'una mateixa espècie?", "o": ["tern", "qüern", "quintern"], "e": "Tern (o terna) és el conjunt de tres; qüern, el grup de quatre; quintern, el de cinc. GNV 18.7 i DNV."},
      {"q": "Quin col·lectiu designa un grup de quatre?", "o": ["qüern", "tern", "quintern"], "e": "Qüern és el grup de quatre (DNV). GNV 18.7."},
      {"q": "Quin col·lectiu designa un plec de cinc fulls?", "o": ["quintern", "qüern", "tern"], "e": "Quintern: plec de cinc fulls (en matemàtiques, també combinació de cinc nombres). DNV."},
      {"q": "Escriu el col·lectiu masculí que designa cent unitats: «Hem repartit un ___ d'entrades.»", "a": ["centenar"], "e": "Centenar és el col·lectiu de cent (forma específica masculina), igual que miler. GNV 18.7 i DNV."},
      {"q": "Quin col·lectiu designa un grup de mil unitats?", "o": ["miler", "milenar", "milé"], "e": "Miler (o miller) i milenar són col·lectius de 1.000 (un miler de cotxes). GNV 18.7 i DNV."},
      {"q": "Quin és el col·lectiu de trenta?", "o": ["trentena", "trentenari", "trentí"], "e": "Els col·lectius tenen la forma de l'ordinal femení: dotzena, vintena, trentena, centena. GNV 18.7."},
      {"q": "Quin col·lectiu designa el conjunt de dos?", "o": ["parell", "dotzena", "tern"], "e": "Parell designa el conjunt de dos (GNV 18.7)."},
      {"q": "Quin multiplicatiu expressa «cinc voltes més»?", "o": ["quíntuple", "quàdruple", "sèxtuple"], "e": "Multiplicatius: doble, triple, quàdruple, quíntuple, sèxtuple. GNV 18.6."},
      {"q": "Quin període designa «quadrimestre»?", "o": ["Quatre mesos", "Quatre anys", "Quatre setmanes"], "e": "Els períodes de mesos: bimestre (2), trimestre (3), quadrimestre (4), semestre (6). GNV 18.7 i DNV."},
      {"q": "Quin període designa «bienni»?", "o": ["Dos anys", "Dos mesos", "Dos segles"], "e": "Els períodes d'anys: bienni (2), trienni (3), quadrienni (4), quinquenni (5). GNV 18.7 i DNV."},
      {"q": "Quina és la grafia correcta del període de tres anys?", "o": ["trienni", "trieni", "triennio"], "e": "Trienni, com bienni, quadrienni i quinquenni: porten -nn- (-enni). GNV 18.7 i DNV."},
      {"q": "Quina és la grafia correcta?", "o": ["quinquenni", "quinqueni", "quinquenio"], "e": "Quinquenni (‘període de cinc anys’) du -nn-. DNV."},
      {"q": "Què significa «octogenari»?", "o": ["Que ha complit huitanta anys i encara no en té noranta", "Que ha complit vuit anys", "Que té huit-cents anys"], "e": "Les franges d'edat: quinquagenari (50), octogenari (80), nonagenari (90). DNV i GNV 18.7."},
      {"q": "Quin prefix culte significa ‘mig’?", "o": ["hemi-", "mono-", "quadri-"], "e": "Hemi- (hemicicle, hemiplegia) i semi- (semicercle) signifiquen ‘mig’. DNV."},
      {"q": "Quin dels prefixos següents NO significa ‘mig’?", "o": ["mono-", "hemi-", "semi-"], "e": "Mono- significa ‘un’ (monogàmia); hemi- i semi- signifiquen ‘mig’. DNV."},
      {"q": "Quin prefix significa ‘quatre’?", "o": ["quadri-", "tri-", "bi-"], "e": "Quadri- (quadrimestre, quadrifoli) i tetra- signifiquen ‘quatre’. DNV."},
      {"q": "Escriu el prefix numèric que falta: «un tauler ___color» (de dos colors).", "a": ["bi", "bi-"], "e": "Bi- significa ‘dos’ (bicolor, bimotor, bimestre, bienni). DNV i GNV 37.7.4."},
      {"q": "Quin prefix expressa ‘un’ en «monogàmia» i «monocotiledoni»?", "o": ["mono-", "bi-", "tri-"], "e": "Mono- ve del grec mónos, ‘un’. DNV."},
      {"q": "Quin prefix té el significat ‘cinc’ en «pentàgon»?", "o": ["penta-", "quinqui-", "cinqu-"], "e": "Penta- (pentàgon, pentadàctil) ve del grec pénte, ‘cinc’; quinqu- ve del llatí (quinquenni). DNV i GNV 18.7."},
      {"q": "Quin prefix té el significat ‘sis’ en «hexàgon» i «hexasíl·lab»?", "o": ["hexa-", "sexi-", "seis-"], "e": "Hexa- ve del grec héx, ‘sis’. DNV."},
      {"q": "Escriu el col·lectiu de vint: «Hi havia una ___ de persones a la plaça.»", "a": ["vintena"], "e": "Els col·lectius tenen la forma de l'ordinal femení: dotzena, vintena, trentena. GNV 18.7 i DNV."},
      {"q": "Escriu el nom del període de quatre anys: «un ___».", "a": ["quadrienni"], "e": "Quadrienni: període de quatre anys, com bienni, trienni i quinquenni. DNV i GNV 18.7."}
    ]
  },
  {
    "id": "df7aa3b7-2fa1-5ea4-8f79-52b1bb6e33f8", "type": "c2_mor_indefinits", "sort_order": 9,
    "title": "Quantitatius i indefinits", "name": "Quantitatius tradicionals (manco, quinzets), gens/cap, altre, tal, tot, qualsevol, ambdós, cert i indefinits arcaics (mant, quelcom, altri, hom, sengles)",
    "content": "Els quantitatius tradicionals i les interferències (gens de gràcia, una mica de pressa), els usos d'altre, tal com a substitut de nom propi, els valors de tot (tota València, les mans totes brutes), qualsevol, ambdós, cert i els indefinits arcaics o formals (mant, quelcom, altri, hom, sengles) (3.2.2).", "icon": "🧮", "color": "#FBE9E7",
    "exercises": [
      {"q": "Completa: «No tinc ___ de pressa.»", "o": ["gens", "cap", "alguna"], "e": "Amb substantius no comptables només és possible gens (sempre amb de): gens de pressa, gens de gràcia; cap s'usa només amb comptables. GNV 19.2.3 i 20.3.e."},
      {"q": "Completa: «Esta broma no té ___ de gràcia.»", "o": ["gens", "cap", "cada"], "e": "Gràcia és un nom no comptable: gens de gràcia (i no *cap gràcia*). GNV 20.3.e."},
      {"q": "Completa: «No hi havia ___ xiquet al carrer.»", "o": ["cap", "gens", "gens de"], "e": "Cap s'usa amb substantius comptables: cap xiquet, cap autobús. GNV 19.2.3."},
      {"q": "Escriu el quantitatiu que falta: «No ens queda ___ d'arròs.»", "a": ["gens"], "e": "Gens modifica substantius no comptables i duu sempre la preposició de: gens d'arròs. GNV 19.2.3 i 20.3.e."},
      {"q": "Quin quantitatiu només s'usa amb substantius comptables?", "o": ["cap", "gens", "massa"], "e": "L'indefinit cap només s'usa amb comptables; amb no comptables s'usa gens. GNV 19.2.3."},
      {"q": "Quina locució quantitativa equival a ‘poc’?", "o": ["un pessic de", "un fum de", "un cabàs de"], "e": "Un pessic de, un raig de i una miqueta (o mica) de signifiquen ‘poc’; un fum de, un cabàs de, un munt de signifiquen ‘molt’. GNV 20.4."},
      {"q": "Quina locució quantitativa NO equival a ‘molt’?", "o": ["un pessic de", "un fum de", "un grapat de"], "e": "Un pessic de equival a ‘poc’ (un pessic de sal); un fum de, un grapat de, un muntó de equivalen a ‘molt’. GNV 20.4."},
      {"q": "Quin quantitatiu té el significat de ‘suficient’?", "o": ["prou", "massa", "gens"], "e": "Prou significa ‘suficient’ (i, en l'ús majoritari valencià, també s'usa amb el valor de bastant); massa indica excés. GNV 20.3.a."},
      {"q": "Completa: «Tots estem ___ cansats després de la caminada.»", "o": ["un poc", "uns pocs", "una poca"], "e": "Poc precedit de un indica que se sobrepassa lleugerament la quantitat habitual: un poc cansats, un poc més alt. GNV 20.3.d."},
      {"q": "Escriu la forma tradicional del quantitatiu en l'expressió «més o ___».", "a": ["manco"], "e": "Manco (‘menys’) es manté en algunes comarques valencianes en més o manco, ni menys ni manco i en l'adverbi almanco. GNV 20.2."},
      {"q": "Quin és el significat de «almanco»?", "o": ["almenys", "quasi", "encara"], "e": "Almanco és un adverbi que equival a almenys. DNV."},
      {"q": "Quin és el valor tradicional de «quinzet»?", "o": ["Moneda o fracció de 25 cèntims de pesseta", "Grup de quinze unitats", "Espai de quinze dies"], "e": "Quinzet és una moneda (25 cèntims de pesseta en el segle XX); la quinzena és el grup de quinze o l'espai de quinze dies. DNV."},
      {"q": "Escriu la paraula tradicional que falta: «Aquell caramel val dos ___.» (monedes de 25 cèntims)", "a": ["quinzets"], "e": "Val dos quinzets: el quinzet era una moneda; els verbs de mesura seleccionen un complement amb valor de quantitat. GNV 32.2.2.c i DNV."},
      {"q": "Quin és el significat de «onça» en «una onça de xocolate»?", "o": ["Porció o pastilla", "Un quilo", "Una barra gran"], "e": "Onça és una antiga unitat de pes i, per extensió, una porció o pastilla: una onça de xocolate. DNV."},
      {"q": "Completa: «Vam parlar de l'encontre de l'___ dia.»", "o": ["altre", "altra", "altres"], "e": "Altre s'usa precedit de l'article o d'un altre indefinit: l'altre dia, una altra pel·lícula. GNV 19.2.2.d."},
      {"q": "Escriu l'indefinit que falta: «Un dia o ___ li ho hauràs de dir.»", "a": ["altre"], "e": "En certes construccions disjuntives, altre s'usa en singular sense especificador: un dia o altre, una cosa o altra. GNV 19.2.2.d."},
      {"q": "Completa: «No hi ha ___ remei.»", "o": ["altre", "un altre", "altres"], "e": "En oracions negatives, altre pot ser l'únic especificador amb el valor de ‘cap altre’: no hi ha altre remei. GNV 19.2.2.d."},
      {"q": "Escriu el pronom que falta: «Ja no treballa per a ___.»", "e": "Altri només s'usa en construccions preposicionals i en contextos molt concrets: treballar per a altri. GNV 19.3.c i DNV.", "a": ["altri"]},
      {"q": "Escriu el pronom que falta: «Mals d'___, rialles són.»", "a": ["altri"], "e": "Altri s'usa exclusivament precedit de preposició: mals d'altri, treballar per a altri. GNV 19.3.c."},
      {"q": "Completa: «Això que ho faça algú ___.»", "o": ["altre", "altri", "altra"], "e": "Fora de les locucions, en lloc d'altri s'usa un altre: algú altre, ningú altre, cap altre. GNV 19.3.c."},
      {"q": "Completa: «No es parla d'___.»", "o": ["altre", "altri", "un altre"], "e": "Altre també funciona com a pronom neutre amb el valor de ‘una altra cosa’: no es parla d'altre. GNV 19.3.c."},
      {"q": "Completa: «Conec ___ gent que pensa igual.»", "o": ["altra", "altre", "altres"], "e": "Amb el substantiu col·lectiu gent, altra pot ser l'únic especificador (o una altra gent). GNV 19.2.2.d."},
      {"q": "Completa: «Ha vingut a veure't un ___ Pere que no conec.»", "o": ["tal", "tant", "tals"], "e": "Tal acompanya el nom d'una persona poc o gens coneguda: un tal Pere. DNV."},
      {"q": "Què significa «tal» en «Tal i tal altre ho han dit»?", "o": ["Suplix el nom d'una persona que no es nomena", "Equival a ‘tal cosa’", "Equival a ‘així’"], "e": "Com a pronom, tal suplix el nom d'una persona que no es nomena: tal i tal altre. DNV."},
      {"q": "Completa: «Ha preguntat per tu una ___ Empar.»", "o": ["certa", "tal", "qualsevol"], "e": "Cert, amb l'article indefinit, equival a tal i modifica un nom propi: una certa Empar. GNV 19.2.2.c."},
      {"q": "Completa: «Hi ha un ___ malestar entre ells.»", "o": ["cert", "algun", "tal"], "e": "En singular, cert sol anar precedit de l'article indefinit: un cert malestar, un cert escàndol. GNV 19.2.2.c."},
      {"q": "Completa: «En ___ manera, cal reconéixer que té raó.»", "o": ["certa", "una certa", "alguna"], "e": "L'article s'omet en algunes expressions amb preposició i en plural: en certa manera, fins a cert punt, en certs casos. GNV 19.2.2.c."},
      {"q": "Quin indefinit NO és adequat en «Han arribat ja ___ estudiants?»", "o": ["certs", "alguns", "diversos"], "e": "Cert no pot usar-se quan es dubta o es qüestiona l'existència de l'entitat; en eixe cas s'usa algun. GNV 19.2.2.c (observació)."},
      {"q": "Escriu la forma de tot que falta: «Es va recórrer ___ València en quatre hores.»", "e": "Amb un topònim, tot designa la globalitat i va sense article: tota València, mig Castelló. GNV 19.2.1.a.", "a": ["tota"]},
      {"q": "Completa: «Els xiquets tenien les mans ___ brutes.»", "o": ["totes", "tot", "tots"], "e": "Amb un adjectiu, tot funciona com a quantitatiu de grau (‘molt’) i concorda amb el substantiu: les mans totes brutes. GNV 19.2.1.a."},
      {"q": "Escriu la forma de tot que falta: «Quan va sentir el seu nom, es va fer ___ roig.»", "e": "Tot amb un adjectiu equival a ‘molt’: es feu tot roig. GNV 19.2.1.a.", "a": ["tot"]},
      {"q": "Escriu la forma que falta: «Les dones tenien els ulls ___ plorosos.»", "a": ["tots"], "e": "Tot com a quantitatiu de grau concorda amb el substantiu: els ulls tots plorosos (‘molt plorosos’). GNV 19.2.1.a."},
      {"q": "Completa: «Els xiquets baixaven l'escala ___ cridant.»", "o": ["tot", "tots", "tan"], "e": "Tot pot introduir una oració de gerundi per a emfatitzar la simultaneïtat: tot cridant. GNV 19.2.1.a (observació)."},
      {"q": "Completa: «___ tres coincidiren en la resposta.»", "o": ["Tots", "Cada", "Tot"], "e": "Tot pot precedir un numeral cardinal, amb o sense article: tots tres / tots els tres. GNV 19.2.1.a."},
      {"q": "Completa: «Deixa'm tres bolígrafs ___.»", "o": ["qualssevol", "qualsevol", "qualsevols"], "e": "Qualsevol es pot posposar al substantiu i concorda en nombre: tres bolígrafs qualssevol (plural purament gràfic). GNV 19.2.1.e."},
      {"q": "Escriu el plural de «un qualsevol»: «uns ___».", "a": ["qualssevol"], "e": "Qualsevol forma el plural afegint -s al primer element del compost: qualssevol. GNV 11.7.a i 19.2.1.e."},
      {"q": "Completa: «Busca una flor ___ i dibuixa-la.»", "o": ["qualsevulla", "qualsevol", "qualssevulla"], "e": "El femení qualsevulla (plural qualssevulla) és arcaic i molt formal: busca una flor qualsevulla. GNV 19.2.1.e (observació)."},
      {"q": "Completa: «Busca unes flors ___ i dibuixa-les.»", "o": ["qualssevulla", "qualsevulla", "qualsevolles"], "e": "El plural femení formal és qualssevulla: unes flors qualssevulla. GNV 19.2.1.e (observació)."},
      {"q": "Completa: «___ professors tenen una opinió pareguda.»", "o": ["Ambdós", "Ambdoses", "Ambdosos"], "e": "Ambdós significa ‘les dos persones o coses esmentades’ i és formal; sol substituir-se per els dos o tots dos. GNV 19.2.1.d."},
      {"q": "Quina és la forma femenina de «ambdós» en registre formal?", "o": ["ambdues", "ambdoses", "ambdosa"], "e": "Ambdós pot ser invariable o variable: ambdós professors / ambdues professores. GNV 19.2.1.d."},
      {"q": "Completa: «Els dos amics portaven ___ carpetes.»", "o": ["sengles", "sengles de", "cada"], "e": "Sengles té un valor distributiu (‘una per a cadascun’); és arcaic i molt formal, i s'hi substituïx per cadascun o cada un. GNV 19.2.1.c."},
      {"q": "Quin és el significat de «sengles» en «A les bessones els van regalar sengles nines»?", "o": ["Una nina per a cada una", "Unes quantes nines", "Les mateixes nines"], "e": "Sengles equival a ‘un per a cadascuna de les entitats esmentades’. GNV 19.2.1.c."},
      {"q": "Completa: «El soroll es repetí ___ vegades durant la nit.»", "o": ["mantes", "manta", "mants"], "e": "Mant, manta, mants, mantes: indefinit arcaic amb valor col·lectiu (‘moltes’). GNV 19.2.2.e i DNV."},
      {"q": "Quin és el significat de «mant» (mantes)?", "o": ["Molt, en gran nombre", "Poc", "Algun"], "e": "Mant és un indefinit arcaic equivalent a nombrós o molts. GNV 19.2.2.e i DNV."},
      {"q": "Quin pronom arcaic equival a «alguna cosa»?", "o": ["quelcom", "res", "altri"], "e": "Quelcom és el correlat afirmatiu arcaic de res; hui s'usa alguna cosa. GNV 19.3.g i DNV."},
      {"q": "Quin estatus té actualment el pronom «hom»?", "o": ["Arcaic i molt formal, substituït per passives pronominals o hi ha qui", "Forma col·loquial habitual", "Plural d'home"], "e": "Hom (subjecte impersonal) es percep com a molt formal; en el seu lloc s'usen es pensava, hi ha qui opina, diuen que... GNV 19.3.e i DNV."},
      {"q": "Quin és el significat de «qualque»?", "o": ["algun", "qualsevol", "cap"], "e": "Qualque és un adjectiu invariable que equival a algun. DNV."}
    ]
  },
  {
    "id": "7564692b-eac7-5385-8bea-29ea707c1ff9", "type": "c2_mor_preposicions", "sort_order": 10,
    "title": "Preposicions: precisió i règim", "name": "Usos particulars de les preposicions simples i compostes (cap/cap a, fins/fins a, com/com a, per/per a), règim verbal, caiguda i canvi de preposició",
    "content": "Precisió en els usos particulars de les preposicions simples i compostes, la distinció entre per i per a davant d'infinitiu, el règim sintàctic del verb, l'elisió i el canvi de preposicions davant de que o d'infinitiu, i els usos no genuïns (3.2.2).", "icon": "🔀", "color": "#E3F2FD",
    "exercises": [
      {"q": "«Se n'han anat ___ allí.»", "o": ["cap", "cap a", "cap en"], "e": "Cap a es reduïx a cap davant dels adverbis demostratius (ací, ahí, allí, allà). GNV 26.4.1."},
      {"q": "«___ on vas, amb esta pluja?»", "o": ["Cap a", "Cap", "Fins"], "e": "Davant d'on no hi ha reducció: cap a on vas? (GNV 26.4.1, taula 26.10)."},
      {"q": "«Han baixat ___ avall.» Escriu la forma correcta de la preposició (cap o cap a).", "a": ["cap"], "e": "Davant dels adverbis de direccionalitat (amunt, avall, avant, endins...) s'usa la forma reduïda cap. GNV 26.4.1."},
      {"q": "«___ d'ací a una setmana no es reunirà el comité d'avaluació.»", "o": ["Fins", "Fins a", "Fins en"], "e": "Davant de sintagmes preposicionals (d'ací a una setmana) s'usa fins, no fins a. GNV 26.4.2."},
      {"q": "«No pareu ___ localitzar-los.»", "o": ["fins a", "fins", "fins que a"], "e": "Davant d'infinitiu, en el sentit temporal, es manté la forma composta fins a; fins s'usa davant de que o de fa. GNV 26.4.2."},
      {"q": "«Van necessitar ___ sis persones per a alçar aquell moble.»", "o": ["fins a", "fins", "fins de"], "e": "En els usos no pròpiament temporals ni espacials es manté fins a: fins a sis persones, fins a un màxim de... GNV 26.4.2."},
      {"q": "«___ els més desinformats ho sabien.» (equival a fins i tot)", "o": ["Fins", "Fins a", "Fins de"], "e": "Com a adverbi equivalent a fins i tot o inclús s'usa la forma curta fins. GNV 26.4.2, observació."},
      {"q": "«Escriu la preposició: No sé ___ quin punt és possible que ho faça.»", "a": ["fins a"], "e": "En els usos no temporals ni espacials, com fins a quin punt, es manté la forma composta fins a. GNV 26.4.2."},
      {"q": "«La malaltia coneguda ___ sida va canviar la medicina.»", "o": ["com a", "com", "per com"], "e": "Amb valor denominatiu ('amb el nom de') s'usa com a: coneguda com a sida. GNV 26.4.3.1."},
      {"q": "«Usava la tapadora del poal ___ escut.»", "o": ["com a", "com", "com de"], "e": "Amb valor substitutiu ('en funció de') s'usa com a: com a escut, com a medecina. GNV 26.4.3.1."},
      {"q": "«___ mínim, s'han de respondre la mitat de les preguntes.»", "o": ["Com a", "Com", "Al"], "e": "Les locucions com a mínim i com a màxim porten com a. GNV 26.4.3.1, observació."},
      {"q": "«Obria uns ulls ___ plats.»", "o": ["com a", "com", "com uns de"], "e": "Amb valor comparatiu i sense determinant s'usa com a: com a plats (però com un plat, amb determinant). GNV 26.4.3.2."},
      {"q": "«El pobre vell plorava ___ un xiquet.» Quina forma segueix la GNV?", "o": ["com", "com a", "com de"], "e": "Quan el sintagma comparatiu va precedit d'un determinant (un, el...), com a es reduïx a com. GNV 26.4.3.2."},
      {"q": "«Escriu la preposició: Obria uns ulls ___ plats.»", "a": ["com a"], "e": "Sense determinant, el comparatiu manté la forma composta com a (com a plats, com a sardines). GNV 26.4.3.2."},
      {"q": "«L'avió ix ___ Londres d'ací a vint minuts.»", "o": ["per a", "per", "cap en"], "e": "Per a introduïx la destinació; per marcaria la ruta (passa per Londres). GNV 26.3.4.1."},
      {"q": "«___ Sant Joan es fan fogueres.»", "o": ["Per", "Per a", "De"], "e": "Per introduïx el complement de temps referit a un període més o menys precís: per Sant Joan. GNV 26.3.4.1."},
      {"q": "«Esta caixa ens servirà ___ guardar les revistes.»", "o": ["per a", "per", "de"], "e": "Quan el subjecte és inanimat i no hi ha intencionalitat, el complement final porta per a. GNV 26.3.4.2."},
      {"q": "«Menges massa ___ aprimar-te.»", "o": ["per a", "per", "en"], "e": "L'oració d'infinitiu que modifica un adverbi o un adjectiu s'introduïx amb per a. GNV 26.3.4.2."},
      {"q": "«Em van posar una multa ___ haver passat el límit de velocitat.»", "o": ["per", "per a", "a"], "e": "Davant d'infinitiu, per introduïx causa o mancança: per haver passat. GNV 26.3.4.2."},
      {"q": "«Tots aquells pisos estan ___ vendre.»", "o": ["per", "per a", "de"], "e": "Per + infinitiu expressa mancança ('encara no s'ha fet'): estan per vendre, estic per afaitar. GNV 26.3.4.2."},
      {"q": "«Escriu la preposició: Encara estic ___ afaitar.» (no ho he fet)", "a": ["per"], "e": "Per + infinitiu indica mancança (encara per fer). GNV 26.3.4.2."},
      {"q": "«No menja ___ no embrutar.»", "o": ["per", "per a", "de"], "e": "Per introduïx els finals amb matís de causa no efectiva, referits a la intenció de no fer una cosa. GNV 26.3.4.2.a."},
      {"q": "Quina d'estes oracions NO és correcta?", "o": ["Menge per tindre fam.", "Menge perquè tinc fam.", "Treballe per guanyar-me la vida."], "e": "Per + infinitiu causal és forçat: no es pot dir menge per tindre fam, sinó menge perquè tinc fam. GNV 26.3.4.2, observació."},
      {"q": "«Gràcies ___ m'ho has dit, ho he sabut a temps.» En registre formal, quina és la forma correcta?", "o": ["que", "a que", "de que"], "e": "En els registres formals cal la caiguda de la preposició davant de que: Gràcies que m'ho has dit. GNV 26.3.5.1."},
      {"q": "«Insistia ___ era innocent.» En registre formal, quina és la forma correcta?", "o": ["que", "en que", "de que"], "e": "El complement de règim perd la preposició davant de que: Insistia que era innocent (Insistia en les seues declaracions). GNV 26.3.5.1."},
      {"q": "«Avisa'm abans ___ te'n vages.»", "o": ["que", "de que", "a que"], "e": "Els complements temporals amb abans, després, des de i fins a perden la preposició davant de que: abans que, fins que. GNV 26.3.5.1."},
      {"q": "«Sempre tarda molt ___ la presa de decisions.»", "o": ["en", "a", "de"], "e": "Tardar es construïx amb en davant de sintagma nominal i amb a davant d'infinitiu (tarden molt a acabar). GNV 26.3.5.2, taula 26.7."},
      {"q": "«Escriu la preposició: Tarden molt ___ acabar la faena.»", "a": ["a"], "e": "Davant d'infinitiu, tardar es construïx amb a: tarden molt a acabar. GNV 26.3.5.2, taula 26.7."},
      {"q": "«M'amenaça ___ dir-li-ho tot.»", "o": ["de", "amb", "en"], "e": "Amenaçar porta amb davant de sintagma nominal (amb la confessió) i de davant d'infinitiu. GNV 26.3.5.2, taula 26.7."},
      {"q": "«S'esforça ___ fer tot el que li manen.»", "o": ["a", "en", "per a"], "e": "Esforçar-se porta en amb sintagma nominal (en tot el que li manen) i a davant d'infinitiu. GNV 26.3.5.2, taula 26.7."},
      {"q": "«Sempre és el primer ___ parlar.»", "o": ["a", "en", "de"], "e": "Ser el primer porta en davant de sintagma nominal (el primer en les coses que li importen) i a davant d'infinitiu. GNV 26.3.5.2."},
      {"q": "«Només pensa ___ ella.» Escriu la preposició.", "a": ["en"], "e": "Pensar és un verb de règim amb en: pensa en tu, pensa en ella. GNV 32.4, taula 32.1."},
      {"q": "«Apel·larem ___ la sentència.» Escriu la preposició.", "a": ["contra"], "e": "Apel·lar (com recórrer) es construïx amb contra: apel·lar contra la sentència. GNV 32.4, taula 32.1."},
      {"q": "«Roser ha renunciat ___ càrrec.» Escriu la preposició contreta amb l'article.", "a": ["al"], "e": "Renunciar és un verb de règim amb a: ha renunciat al càrrec. GNV 32.4, taula 32.1."},
      {"q": "«Va nàixer ___ Morella però ara viu ___ Benicarló.»", "o": ["a / a", "en / en", "de / per"], "e": "Davant de noms propis de lloc s'usa la preposició a: nàixer a Morella, viure a Benicarló. GNV 26.3.1.1."},
      {"q": "«Són parella però viuen ___ cases diferents.»", "o": ["en", "a", "per"], "e": "Davant de noms sense determinant (i davant d'indefinits o demostratius) s'usa en: en cases diferents, en este carrer. GNV 26.3.1.1."},
      {"q": "«Treballa ___ valent i no es queixa mai.»", "o": ["de", "amb", "en"], "e": "De pot introduir complements de manera: treballa de valent, parla de mala manera. GNV 26.3.3."},
      {"q": "«S'ha decidit ___ model més econòmic.» (contracció amb l'article)", "o": ["pel", "al", "del"], "e": "Decidir-se és un verb de règim amb per: s'ha decidit pel model més econòmic. GNV 32.4, taula 32.1."},
      {"q": "«No en vull, ___ pa.»", "o": ["de", "per", "a"], "e": "La preposició de és obligatòria en les dislocacions a la dreta: No en vull, de pa. GNV 26.3.3.2."},
      {"q": "«Entre tu i ___ ho farem tot.» Escriu el pronom.", "a": ["jo"], "e": "Entre, en esta construcció, no funciona com una veritable preposició i pren el pronom en cas recte: entre tu i jo. GNV 26.5.3, observació."},
      {"q": "Quina preposició formal significa 'a canvi de' (M'ho va donar ___ res)?", "o": ["barata", "ultra", "vers"], "e": "Barata és sinònima de a canvi de; ultra equival a 'a més de' i vers a 'cap a'. GNV 26.5.1, 26.5.7 i 26.5.8."},
      {"q": "«___ l'oferta tradicional, el restaurant inclou un menú baix en calories.» Quina preposició formal significa 'a més de'?", "o": ["Ultra", "Barata", "Envers"], "e": "Ultra és una forma arcaica usada en registres formals amb el sentit de 'de més a més'. GNV 26.5.7."},
      {"q": "«L'estima de l'actor ___ el teatre és sincera.» Quina preposició formal i literària s'usa?", "o": ["envers", "contra", "sense"], "e": "Vers i envers mantenen ús literari amb sentit de direcció, també figurat: l'estima de l'actor envers el teatre. GNV 26.5.8."},
      {"q": "«Això no fa gust ___ res.»", "o": ["de", "a", "amb"], "e": "En valencià, el sabor es dona amb fer gust de: fa gust de peix, no fa gust de res (DNV, gust)."},
      {"q": "«Caminava ___, sense pressa.» Quina és la locució adverbial genuïna del DNV?", "o": ["a poc a poc", "poc a poc", "de poc en poc"], "e": "El DNV registra la locució a poc a poc ('lentament, a espai'); sense la primera a no és genuïna."}
    ]
  },
  {
    "id": "e6dde65d-7095-5649-a487-c9bee40db539", "type": "c2_mor_preposicions_locucions", "sort_order": 11,
    "title": "Preposicions en la fraseologia i baix, davall, sota", "name": "Preposicions en la fraseologia i en les locucions prepositives sense interferències; baix, davall i sota enfront de dalt, damunt i sobre",
    "content": "Ús genuí de les preposicions en la fraseologia i de les locucions prepositives evitant interferències (en base a, a nivell de...), i distinció entre baix, davall i sota enfront de dalt, damunt i sobre (3.2.2).", "icon": "⬇️", "color": "#E8EAF6",
    "exercises": [
      {"q": "«El concert es va suspendre ___ del mal oratge.»", "o": ["a causa", "a base", "a càrrec"], "e": "A causa de indica la raó per la qual es fa una cosa (també per culpa de, per raó de). GVB 32.4."},
      {"q": "«Ha preparat un còctel ___ suc de tomaca i vodka.»", "o": ["a base de", "a força de", "a càrrec de"], "e": "A base de indica els ingredients principals d'un menjar o una beguda. GVB 32.2."},
      {"q": "«El dinar és ___ l'empresa.»", "o": ["a càrrec de", "a causa de", "a costa de"], "e": "A càrrec de assenyala qui assumix una despesa o una faena. GVB 32.3."},
      {"q": "«Ha escrit el llibre ___ molts esforços.»", "o": ["a costa de", "a càrrec de", "a falta de"], "e": "A costa de indica que alguna cosa s'ha aconseguit amb sacrificis i penalitats. GVB 32.6."},
      {"q": "«___ vi, beurem aigua.»", "o": ["A falta de", "A força de", "A mitjan"], "e": "A falta de indica que, si no es té una cosa, se substituirà per una altra. GVB 32.7."},
      {"q": "«Va votar ___ la proposta i es va aprovar per unanimitat.»", "o": ["a favor de", "en contra de", "a causa de"], "e": "A favor de expressa que s'és partidari d'una opció; en contra de n'indica l'oposició. GVB 32.8 i 32.27."},
      {"q": "«Ha aprovat les oposicions ___ estudiar.» (insistint-hi cada dia)", "o": ["a força d'", "a base d'", "a causa d'"], "e": "A força de (o a còpia de) indica que s'ha aconseguit alguna cosa repetint una acció amb esforç. GVB 32.10."},
      {"q": "«Es va publicar en la web ___ garantir-ne la màxima difusió.»", "o": ["a fi de", "a falta de", "a mitjan"], "e": "A fi de, igual que per tal de, indica la finalitat. GVB 32.9."},
      {"q": "Quina és la formulació genuïna per a «*En base a estes dades, analitzarem el sector»?", "o": ["A partir d'estes dades, analitzarem el sector.", "En base a estes dades, analitzarem el sector.", "Baix estes dades, analitzarem el sector."], "e": "La locució en base a no figura en el DNV; per a assenyalar el punt de partida d'un raonament s'usa a partir de (GVB 32.14)."},
      {"q": "Quina opció evita la interferència de «*Hi ha problemes a nivell de comunicació»?", "o": ["Hi ha problemes de comunicació.", "Hi ha problemes a nivell de comunicació.", "Hi ha problemes al nivell de comunicació."], "e": "El DNV només registra a (o al) nivell de amb el sentit 'a la mateixa altura que', no amb el d'àmbit: es resol amb de comunicació o pel que fa a la comunicació."},
      {"q": "En quin cas la locució «a nivell de» és genuïna?", "o": ["La pressió atmosfèrica és més alta a nivell del mar.", "Cal millorar la gestió a nivell d'empresa.", "A nivell de govern no s'ha decidit res."], "e": "Segons el DNV, a nivell de és 'a la mateixa altura que' (a nivell del mar); amb el sentit d'àmbit és un calc, millor pel que fa a, en l'àmbit de."},
      {"q": "«Han pactat ___ les pròximes eleccions.»", "o": ["amb vista a", "en vista a", "a vista a"], "e": "Amb vista a (o de cara a) indica el propòsit o la intenció; en vista de, en canvi, és 'considerant'. GVB 32.22 i 32.32."},
      {"q": "«___ l'èxit, és millor no insistir-hi.»", "o": ["En vista de", "A vista de", "En virtut de"], "e": "En vista de indica que l'acció es fa considerant o atenent alguna cosa. GVB 32.32."},
      {"q": "«El secretari té veu però no vot, ___ del reglament.»", "o": ["en virtut", "en vista", "a favor"], "e": "En virtut de expressa que un fet té lloc per l'acció d'alguna cosa (una norma, un acord). GVB 32.31."},
      {"q": "«Les obres s'efectuaran ___ el projecte de rehabilitació.»", "o": ["d'acord amb", "d'acord a", "en acord amb"], "e": "La locució genuïna és d'acord amb; d'acord a és un calc del castellà. GVB 32.24."},
      {"q": "«___ els incendis del cap de setmana, se sospita que han sigut intencionats.»", "o": ["En relació amb", "En relació a", "En relació de"], "e": "En relació amb (o amb relació a) fa referència a un tema determinat. GVB 32.30."},
      {"q": "«No pots deixar de fer una cosa ___ fracassar.»", "o": ["per por de", "per por a", "amb por de"], "e": "La locució és de por de, amb la variant per por de. GVB 32.25."},
      {"q": "«___ arribar a les nou, arribaran a les deu.»", "o": ["En compte d'", "En compte a", "En contra d'"], "e": "En compte de (o per compte de, en comptes de) expressa que una cosa en substituïx una altra. GVB 32.26."},
      {"q": "«Farem una cosa o una altra ___ del dia que isca.»", "o": ["en funció", "en funcions", "a funció"], "e": "En funció de indica que una acció està supeditada a una altra. GVB 32.28."},
      {"q": "«Vaig aconseguir una entrada ___ la meua cosina.»", "o": ["per mitjà de", "per mig de", "pel mitjà de"], "e": "Per mitjà de assenyala la persona o l'instrument que permet arribar a un fi (sinònim: a través de, mitjançant). GVB 32.33."},
      {"q": "«Es pot seguir el curs ___ Internet.»", "o": ["a través d'", "a travers d'", "en través d'"], "e": "A través de indica, en sentit figurat, l'instrument o el mitjà. GVB 32.17."},
      {"q": "«El juí es va celebrar ___ dos anys.» (quan en van passar dos)", "o": ["al cap de", "al llarg de", "a mitjan"], "e": "Al cap de indica que l'acció es fa al final d'un espai de temps. GVB 32.18."},
      {"q": "«Ha viatjat molt ___ la seua vida.»", "o": ["al llarg de", "al cap de", "a mitjan"], "e": "Al llarg de indica que l'acció té lloc dins d'un espai de temps. GVB 32.19."},
      {"q": "«Cal tallar els arbres ___ terra.»", "o": ["arran de", "al cap de", "a través de"], "e": "Arran de situa dos entitats a la vora, quasi tocant-se (i, figuradament, 'a conseqüència de'). GVB 32.23."},
      {"q": "«Se'n va anar ___ dinar.»", "o": ["a mitjan", "a la mitjan", "en mitjan"], "e": "A mitjan va seguida d'un substantiu sense determinant: a mitjan dinar, a mitjan vesprada. GVB 32.13."},
      {"q": "«Va posar en ___ els mèrits de l'homenatjat.»", "o": ["relleu", "relleus", "rellevància"], "e": "La locució verbal genuïna és posar en relleu ('fer ressaltar'), segons el DNV (relleu)."},
      {"q": "«Des de dalt de l'escenari les coses es veuen d'una manera, i des de ___, d'una altra.»", "o": ["baix", "davall", "sota"], "e": "Baix s'oposa a dalt i expressa 'en la part baixa': des de dalt, des de baix. GVB 35.3.4."},
      {"q": "«Berenàrem ___ d'una carrasca.»", "o": ["davall", "baix", "damunt"], "e": "Davall indica localització en la part inferior en direcció vertical; no s'usa baix amb este valor. GNV 27.4.2.3.b."},
      {"q": "«Fa calor: lleva't el llençol de damunt i deixa només el de ___.»", "o": ["davall", "baix", "dins"], "e": "Damunt i davall s'oposen en l'eix vertical: el llençol de damunt i el de davall. GVB 35.3.2."},
      {"q": "«No volen viure ___ la seua tutela.»", "o": ["sota", "baix", "dalt"], "e": "Sota té caràcter formal i expressa relacions de submissió, subordinació o dependència. GVB 31.17."},
      {"q": "«Declare ___ jurament que les dades són certes.»", "o": ["sota", "baix", "dalt"], "e": "Sota s'usa en sentit figurat amb jurament, pressió, els efectes de... GVB 31.17."},
      {"q": "«Estàvem a tres graus ___ zero.»", "o": ["sota", "baix", "dins"], "e": "Per a la temperatura inferior a zero s'usa sota o per davall de; no baix. GVB 31.17."},
      {"q": "«Estàvem a quatre graus ___ zero.»", "o": ["sobre", "dalt", "baix"], "e": "Per a la temperatura superior a zero s'usa sobre o per damunt de. GVB 31.16."},
      {"q": "«T'he deixat la jaqueta ___ la cadira.»", "o": ["damunt de", "baix de", "davall de"], "e": "Amb contacte físic en la part superior s'usa damunt (o sobre): damunt de la cadira. GNV 27.4.2.3.a."},
      {"q": "«Penja el quadre ___ del llit, a la paret.»", "o": ["dalt", "davall", "baix"], "e": "Dalt indica 'en la part alta' sense contacte; damunt implica contacte: penja el quadre dalt del llit. GNV 27.4.2.3.a."},
      {"q": "«Mira ___ del coixí, a veure si ho has deixat allí.»", "o": ["davall", "baix", "dalt"], "e": "Davall (o sota) indica la part inferior en l'eix vertical: davall del coixí. GNV 26.5.6."},
      {"q": "Quina de les tres formes NO és acceptable amb el valor de 'davall la taula'?", "o": ["Baix la taula", "Davall la taula", "Sota la taula"], "e": "No és acceptable baix seguit de complement amb el valor de davall o sota. GNV 27.4.2.3.b, observació."},
      {"q": "Quina frase és correcta pel que fa a la preposició de?", "o": ["Baix del bancal hi ha una bassa, i dalt, un mas.", "Baix el bancal hi ha una bassa, i dalt, un mas.", "Baix amb el bancal hi ha una bassa, i dalt, un mas."], "e": "Baix, fora, prop i lluny requerixen la preposició de davant d'un complement nominal. GVB 35.3."},
      {"q": "«Ja parlarem demà ___ la redistribució de l'espai.»", "o": ["sobre", "damunt", "davall"], "e": "Sobre introduïx el tema d'un acte de parla o de comunicació. GNV 26.5.6."},
      {"q": "«___ de castigar-lo, encara li va pegar.» (a més de)", "o": ["Damunt", "Dalt", "Davall"], "e": "Sobre i damunt de poden tindre el valor quantitatiu de 'a més de': damunt de castigar-lo. GNV 26.5.6."},
      {"q": "«Ha callat ___ por de fer el ridícul.» Escriu la preposició.", "a": ["de", "per"], "e": "La locució és de por de (o per por de): indica que no es fa una cosa pel temor que inspira. GVB 32.25."},
      {"q": "«A ___ d'estudiar, ha aprovat les oposicions.» Escriu el nom de la locució (esforç repetit).", "a": ["força", "còpia"], "e": "A força de i a còpia de indiquen que s'ha aconseguit alguna cosa repetint-hi l'esforç. GVB 32.10."},
      {"q": "«Tira-li la carta per ___ de la porta.» Escriu l'adverbi.", "a": ["davall"], "e": "Davall (o sota) indica la part inferior en direcció vertical, amb contacte o sense. GVB 35.3.2."},
      {"q": "«Es va plantar davant ___ mi.» Escriu la preposició.", "a": ["de"], "e": "L'adverbi preposicional va seguit de de + pronom personal: davant de mi, darrere de nosaltres. GNV 27.4.2.2.a."},
      {"q": "«Posa la caixa ___ la taula, tocant-la.» Escriu l'adverbi (damunt o dalt).", "a": ["damunt"], "e": "Damunt implica contacte amb la superfície; dalt no pressuposa contacte. GNV 27.4.2.3.a."},
      {"q": "«El llençol de damunt i el de ___.» Escriu l'adverbi que s'oposa a damunt.", "a": ["davall"], "e": "Damunt i davall s'oposen en l'eix vertical. GVB 35.3.2."},
      {"q": "«Els pelegrins es dirigien ___ la mesquita.» Escriu la preposició literària equivalent a cap a.", "a": ["envers", "vers"], "e": "Vers i envers són preposicions clàssiques d'ús literari, amb valor de direcció. GVB 31.19."},
      {"q": "«Va actuar així ___ tal de confondre'l.» Escriu la preposició.", "a": ["per"], "e": "Per tal de és sinònim de a fi de i expressa la finalitat. GVB 32.9."}
    ]
  },
  {
    "id": "1affc211-4cb5-5371-8564-d8f556fb7e9a", "type": "c2_mor_adverbis", "sort_order": 12,
    "title": "Adverbis: negació expletiva, usos formals i lexicalitzacions", "name": "Negació expletiva; corrents, inclusivament, exclusivament, escaig; usos formals (enlloc, força, dempeus, enjorn, sendemà...) i lexicalitzacions (alhora, potser, sobretot...)",
    "content": "Negació expletiva amb verbs de temor, temporals i comparatives; ús particular d'alguns adverbis i locucions adverbials (corrents, inclusivament, exclusivament, escaig); usos formals de certs adverbis i lexicalització de locucions com aleshores, alhora, enlaire, potser, sobretot i enlloc (3.2.2).", "icon": "🧭", "color": "#E0F7FA",
    "exercises": [
      {"q": "Quina d'estes oracions conté un no expletiu, és a dir, sense valor negatiu?", "o": ["Prepara el sopar abans que no vinga la mare.", "Si no vens, no prepararé el sopar.", "No vull que vinga la mare."], "e": "Amb abans (que) i fins que l'adverbi no pot aparéixer sense valor negatiu: abans que (no) vinga. GNV 27.7.2.2.b."},
      {"q": "Quina oració equival a «No prepararé el sopar fins que vinga la mare»?", "o": ["No prepararé el sopar fins que no vinga la mare.", "Prepararé el sopar fins que vinga la mare.", "No prepararé el sopar si vinga la mare."], "e": "Després de fins que, el no és opcional i expletiu: fins que (no) vinga. GNV 27.7.2.2.b."},
      {"q": "Quina oració equival a «M'agrada més anar al teatre que al cine»?", "o": ["M'agrada més anar al teatre que no al cine.", "No m'agrada anar al teatre.", "M'agrada més anar al cine que al teatre."], "e": "En les comparatives de superioritat el no expletiu és opcional: que (no) al cine. GNV 27.7.2.2.c."},
      {"q": "Segons la GNV, la negació expletiva en valencià...", "o": ["és opcional i ha perdut vitalitat", "és obligatòria en les comparatives", "és sempre un error"], "e": "Era molt habitual en la llengua clàssica i es manté en la majoria de parlars, però en valencià ha perdut vitalitat. GNV 27.7.2.2, observació."},
      {"q": "Quin valor té «res» en «Si vols res, avisa'm»?", "o": ["alguna cosa", "cap cosa", "tot"], "e": "Ningú, res, mai i enlloc tenen valor afirmatiu en condicionals, interrogatives i dubitatives: Si vols res = si vols alguna cosa. GNV 27.7.2.3.c."},
      {"q": "Quin valor té «mai» en «Has anat mai a les Columbretes?»", "o": ["alguna vegada", "cap vegada", "sempre"], "e": "En contextos interrogatius mai pot tindre valor afirmatiu ('alguna vegada'); amb no, en canvi, torna a ser negatiu. GNV 27.7.2.3.c."},
      {"q": "«He dinat ___, i ara em trobe malament.»", "o": ["corrents", "corrent", "corrint"], "e": "Corrents és un adverbi amb el valor de 'molt de pressa'; no es confon amb corrent ni amb el gerundi corrent. GVB 34.4.8."},
      {"q": "«Ho feu tot ___, i no n'encerteu ni una.» Escriu l'adverbi que significa 'molt de pressa'.", "a": ["corrents"], "e": "Corrents: 'de pressa, a gran velocitat' (DNV): anem corrents, de pressa i corrents. GVB 34.4.8."},
      {"q": "«Tancat per vacances fins al dia 30 ___.» Escriu l'adverbi que indica que el dia 30 també s'inclou.", "a": ["inclusivament"], "e": "Inclusivament significa 'amb inclusió': fins al dia 23 d'abril inclusivament. GVB 34.4.10."},
      {"q": "Quin adverbi significa 'excloent qualsevol altra cosa'?", "o": ["exclusivament", "inclusivament", "corrents"], "e": "El DNV defineix exclusivament com 'excloent qualsevol altra cosa': Acceptem exclusivament targetes de crèdit."},
      {"q": "Què vol dir «Són quinze euros i escaig»?", "o": ["Quinze euros i una petita fracció més", "Quinze euros justos", "Quasi quinze euros"], "e": "Escaig és la fracció que excedix una quantitat redona: sis euros i escaig (DNV)."},
      {"q": "«El meu fill pesa trenta quilos i ___.» Escriu la paraula.", "a": ["escaig"], "e": "Escaig, nom masculí, és la fracció que excedix una quantitat redona (DNV)."},
      {"q": "«___ d'anar al cine, anirem a un concert.»", "o": ["En lloc", "Enlloc", "En cap lloc"], "e": "En lloc de és una locució preposicional ('en substitució de'); enlloc és l'adverbi negatiu d'en cap banda (DNV)."},
      {"q": "«No he trobat el llibre que em recomanares ___.»", "o": ["enlloc", "en lloc", "a lloc"], "e": "Enlloc és l'adverbi que indica 'en cap lloc' (sinònim: en cap banda). GVB 35.5.3."},
      {"q": "«No l'he trobat ___.» Escriu en una sola paraula l'adverbi que equival a 'en cap banda'.", "a": ["enlloc"], "e": "Enlloc s'escriu en una paraula quan és l'adverbi negatiu. GVB 35.5.3."},
      {"q": "Quin valor té «força» en «Té força diners»?", "o": ["molts, bona cosa de", "pocs", "cap"], "e": "Força equival a 'molt' o 'bona cosa de'; és viu en algunes comarques valencianes i literari en la resta. GNV 20.3.c."},
      {"q": "Quina de les oracions usa correctament l'adverbi «força»?", "o": ["Té força diners.", "No té força diners.", "Té prou força diners."], "e": "Força només s'usa en oracions afirmatives (GVB, quantitatius)."},
      {"q": "Quina locució és sinònima de «de peus» ('dret, descansant sobre els peus')?", "o": ["a peu dret", "a peu pla", "de peus a terra"], "e": "El DNV registra de peus i a peu dret com a locucions adverbials amb el mateix sentit (a més de dempeus)."},
      {"q": "«Ens va ordenar que ens mantinguérem ___.» Escriu l'adverbi que significa 'de peus'.", "a": ["dempeus"], "e": "Dempeus és l'adverbi (en una paraula) de 'de peus, descansant sobre els peus' (DNV)."},
      {"q": "«El teu germà parla ___ per telèfon.» (sempre, contínuament)", "o": ["a tothora", "a tot hora", "tot l'hora"], "e": "A tothora (o tothora) és la locució adverbial de 'sempre, contínuament' (DNV; GNV 27.5)."},
      {"q": "«No tingueu pressa, que encara és ___.»", "o": ["enjorn", "enhora", "en jornal"], "e": "Enjorn fa referència a les primeres hores del matí o de la nit i, per extensió, a un moment anterior a l'oportú. GVB 36.2.7."},
      {"q": "«Sempre s'alça ___.» Escriu l'adverbi (enjorn o d'hora).", "a": ["enjorn", "d'hora"], "e": "Enjorn (o d'hora) indica un moment més primerenc del normal (DNV: gitar-se enjorn). GVB 36.2.7."},
      {"q": "«Va firmar ___ pressió psicològica.»", "o": ["sota", "baix", "dalt"], "e": "Sota és la preposició formal de sentit figurat: sota pressió, sota jurament, sota la tutela de. GVB 31.17."},
      {"q": "«Ens va assegurar que ___ enviaria la carta.»", "o": ["l'endemà", "la vespra", "l'anit"], "e": "Amb un verb en passat s'usa l'endemà (el dia següent al que es pren com a referència) i el condicional. GNV 28.4."},
      {"q": "Quin és el dia anterior a aquell que es pren com a referència?", "o": ["la vespra", "l'endemà", "el sendemà"], "e": "La vespra és 'el dia anterior'; l'endemà i el sendemà són 'el dia següent'. GNV 27.5."},
      {"q": "Quina forma és sinònima d'«endemà» i admet la locució «al ___»?", "o": ["sendemà", "sendemai", "senderà"], "e": "El DNV registra sendemà com a variant d'endemà, i al sendemà com a locució 'el dia següent a aquell a què es fa referència'."},
      {"q": "Quin adverbi significa 'en el moment que es pren com a referència'?", "o": ["aleshores", "a les hores d'ara", "adés"], "e": "Aleshores (o llavors) és anafòric: situa l'acció en el moment de referència. A hores d'ara és 'actualment'. GNV 27.5."},
      {"q": "«Com que feia temps que no sabia res d'ell, li vaig telefonar, i ___ em va dir que no el molestara més.»", "o": ["aleshores", "a les hores", "a l'ora"], "e": "Aleshores s'escriu en una paraula quan és l'adverbi de temps, equivalent a llavors (que és la forma general). GVB 36.2.14."},
      {"q": "Quina de les locucions NO significa 'actualment'?", "o": ["a hora horada", "a l'hora d'ara", "a hores d'ara"], "e": "A hora horada és 'en l'últim moment'; a hores d'ara, a l'hora d'ara i a les hores d'ara són 'en estos moments'. GVB 36.3.3 i 36.3.4."},
      {"q": "«Reia i plorava ___.»", "o": ["alhora", "a l'hora", "a lhora"], "e": "Alhora és l'adverbi lexicalitzat de 'al mateix temps' (DNV: arribàrem tots alhora). GVB 36.2.13."},
      {"q": "«Ens trobarem ___ de dinar.»", "o": ["a l'hora", "alhora", "a la hora"], "e": "En el sentit de 'en el moment del dinar' s'escriu en tres mots (a + l'hora); alhora és 'al mateix temps'."},
      {"q": "«Reia i plorava ___.» Escriu l'adverbi de simultaneïtat en una sola paraula.", "a": ["alhora"], "e": "Alhora: 'al mateix temps, a la vegada' (DNV). GVB 36.2.13."},
      {"q": "«El tren ha arribat ___.» (puntualment)", "o": ["a hora", "a l'hora", "a les hores"], "e": "A hora significa 'en el moment assenyalat o previst'; a hora horada és 'en l'últim moment'. GVB 36.3.2 i 36.3.3."},
      {"q": "Què vol dir «Sempre ho fas tot a hora horada»?", "o": ["En l'últim moment, quasi fent tard", "Amb molta antelació", "A l'hora exacta"], "e": "A hora horada indica que una acció es fa en l'últim moment, quasi fent tard (sinònim: a última hora). GVB 36.3.3."},
      {"q": "Quina d'estes formes s'escriu en una sola paraula?", "o": ["enlaire", "en laire", "en-laire"], "e": "El DNV registra enlaire com a adverbi ('a certa distància de terra'), amb la variant en l'aire."},
      {"q": "Què vol dir «El punt més important de la reunió ha quedat enlaire»?", "o": ["Ha quedat pendent, sense resoldre", "S'ha resolt per unanimitat", "S'ha ajornat a l'any vinent"], "e": "Enlaire té també el sentit de 'pendent o sense resoldre' (DNV)."},
      {"q": "Quina és la grafia de l'adverbi que denota la possibilitat d'allò que es diu?", "o": ["potser", "pot ser", "pot-ser"], "e": "Potser és l'adverbi modal, una paraula composta (potser el veuré demà); pot ser és forma verbal (pot ser que vinga). GNV 27.7.1."},
      {"q": "«___ el veuré demà.» Escriu l'adverbi de dubte en una sola paraula.", "a": ["potser"], "e": "Potser: 'denota la possibilitat d'allò que es diu' (DNV). GNV 27.7.1."},
      {"q": "«Ella és, ___, una gran professional.»", "o": ["sobretot", "sobre tot", "sobre-tot"], "e": "Sobretot és l'adverbi lexicalitzat de 'principalment' (DNV); en dos mots és preposició + tot."},
      {"q": "En quina frase s'escriu «sobre tot» en dos mots (preposició + tot)?", "o": ["Ha escrit un informe sobre tot el que va ocórrer.", "Ho vull, sobre tot, ben fet.", "Sobre tot, sigues discret."], "e": "Sobre tot és preposició + tot ('acerca de tot'); amb el sentit de 'principalment' és l'adverbi sobretot."},
      {"q": "Quin adverbi indica 'seguit, sense interrupció' en «Hem hagut de treballar dos dies ___»?", "o": ["arreu", "enlloc", "alhora"], "e": "Arreu pot indicar que una acció es fa seguida, sense interrupció (i també 'per totes les bandes'). GVB 34.4.6."},
      {"q": "Què vol dir «Hem obeït a la força»?", "o": ["Contra la pròpia voluntat, per no poder fer altra cosa", "Amb molta energia", "Amb gust"], "e": "A la força expressa que es fa una cosa en contra de la pròpia voluntat. GNV 27.3; GVB 34.5.14."},
      {"q": "Quin adverbi és antic o literari per a 'sempre'?", "o": ["tostemps", "adés", "enguany"], "e": "Tostemps és un adverbi antic o literari amb el valor de sempre (DNV: «ant.»). GVB 36.2.10."},
      {"q": "Quin adverbi es refereix a un passat immediat molt pròxim al moment actual?", "o": ["adés", "enguany", "anit"], "e": "Adés indica un passat immediat (literàriament també suara): Hem passat adés a saludar-te. GVB 36.2.3."},
      {"q": "Quan va passar allò que s'esdevingué «anit»?", "o": ["La nit immediatament anterior al dia de hui", "La nit de demà", "Fa un any"], "e": "Anit situa l'acció en la nit anterior al dia en què ens trobem. GVB 36.2.18."},
      {"q": "«El coneixen ___.» (per totes les bandes)", "o": ["pertot arreu", "enlloc", "arrere"], "e": "Pertot, arreu, a tot arreu i pertot arreu signifiquen 'per totes les bandes'. GVB 35.5.2."}
    ]
  },
  {
    "id": "1c30170a-55f6-5ef0-863d-c731aea2b168", "type": "c2_mor_conjuncions", "sort_order": 13,
    "title": "Conjuncions i connectors: propietat i registre", "name": "Substitució de calcs (conforme, segons s'acosta), mentre, mentre que, mentrestant, mentrimentres; col·locació de però; conjuncions arcaiques i literàries; connectors formals",
    "content": "Propietat en l'ús de conjuncions i connectors, substitució d'interferències i calcs, usos de mentre(s), mentre(s) que i mentrestant/mentrimentres, col·locació diversa de però, conjuncions arcaiques (jatsia, car, puix) i connectors del discurs formal (3.2.2).", "icon": "🔗", "color": "#FFF3E0",
    "exercises": [
      {"q": "«Recorda que has de situar els convidats ___ decidírem.»", "o": ["tal com", "conforme", "segons que"], "e": "El calc conforme com a conjunció se substituïx per tal com (DNV: «Ho hem fet tal com ens vas dir»); en el DNV conforme només és adjectiu o interjecció."},
      {"q": "«___ que s'acosta l'estiu, m'emocione més.» Escriu la paraula inicial de la locució que substituïx el calc *segons s'acosta (a ___ que).", "a": ["mesura"], "e": "A mesura que expressa l'avanç paral·lel de dos processos (DNV, mesura: «A mesura que el temps passava, perdia popularitat»)."},
      {"q": "«Joana treballa moltes hores, ___ jo em limite a complir estrictament l'horari.»", "o": ["mentre que", "mentre", "mentrestant"], "e": "Mentre que (o mentres que) té valor adversatiu; mentre, valor temporal. GNV 34.4.4, observació."},
      {"q": "«___ tu prepares l'ensalada, jo pare taula.»", "o": ["Mentre", "Mentre que", "Mentrestant que"], "e": "Per a la simultaneïtat temporal s'usa mentre (o mentres), no mentre que. GNV 34.5.7."},
      {"q": "«___ estava a casa, va sonar el telèfon.»", "o": ["Mentre", "Mentre que", "Tanmateix"], "e": "Mentre introduïx una subordinada temporal de simultaneïtat; mentre que és adversativa. GNV 34.4.4 i 34.5.7."},
      {"q": "«Jo estava treballant i ell, ___, em pots dir què feia?» Escriu l'adverbi de simultaneïtat que comença per mentre- (una paraula).", "a": ["mentrestant", "mentrimentres"], "e": "Mentrestant (col·loquialment mentrimentres, també entretant) relaciona dos accions simultànies. GVB 36.2.22."},
      {"q": "Quina forma és col·loquial i sinònima de «mentrestant»?", "o": ["mentrimentres", "tanmateix", "aleshores"], "e": "Mentrimentres és l'adverbi col·loquial sinònim de mentrestant (també conjunció, 'mentre'). DNV; GVB 36.2.22."},
      {"q": "Quina afirmació sobre «mentre» i «mentres» és correcta?", "o": ["Mentres no és incorrecta, però en registres formals s'ha preferit mentre.", "Mentres és un castellanisme inadmissible.", "Només mentres és normativa."], "e": "La s adverbial de mentres no es pot considerar incorrecta ni castellanitzant, però en els registres formals s'evita. GNV 34.5.7, observació."},
      {"q": "En quina oració té «mentre que» valor adversatiu?", "o": ["Ell és molt ordenat, mentre que el seu germà ho deixa tot per terra.", "Mentre que dormia, va sonar el telèfon.", "Estudia mentre que escolta música."], "e": "Mentre que expressa contrast entre dos elements; per a la simultaneïtat s'usa mentre. GNV 34.4.4."},
      {"q": "Quina oració equival a «Però Joan no sabia res de tot això»?", "o": ["Joan, però, no sabia res de tot això.", "Joan, car, no sabia res de tot això.", "Joan, jatsia, no sabia res de tot això."], "e": "Però pot aparéixer en posicions diferents de la inicial, amb valor d'adverbi connectiu: Joan, però, no sabia res. GNV 34.4.4, observació."},
      {"q": "«Joan, ___, no sabia res de tot això.» Escriu la conjunció adversativa que pot anar darrere del subjecte.", "a": ["però"], "e": "Però pot col·locar-se després del primer element: Joan, però, no sabia res. GNV 34.4.4, observació."},
      {"q": "Quina conjunció arcaica significa 'encara que'?", "o": ["jatsia", "puix", "car"], "e": "El DNV marca jatsia com a conjunció antiga amb el sentit d'encara que; puix i car són causals."},
      {"q": "«___ que ho disposa la llei, haurem de fer-ho així.» Escriu la conjunció causal formal.", "a": ["puix"], "e": "Puix que és causal ('atés que, com que', DNV). GNV 34.5.4."},
      {"q": "Quina conjunció és molt formal, literària i de valor causal?", "o": ["car", "jatsia", "sinó"], "e": "Car és una conjunció causal molt formal, d'ús restringit als àmbits literaris. GNV 34.5.4, observació."},
      {"q": "Quina d'estes conjuncions NO és causal?", "o": ["jatsia", "puix que", "atés que"], "e": "Jatsia és concessiva (arcaisme); puix que i atés que són causals. GNV 34.5.4; DNV."},
      {"q": "«Hem anul·lat l'acte ___ no s'havia presentat ningú.»", "o": ["per tal com", "per tal de", "a fi de"], "e": "Per tal com és causal ('perquè', DNV); per tal de i a fi de són finals i van amb infinitiu. GVB 32.9."},
      {"q": "«No m'ho ha dit ella ___ el seu germà.» Escriu la conjunció substitutiva.", "a": ["sinó"], "e": "Sinó, en una paraula i amb accent, afirma el segon membre i nega el primer. GNV 34.4.4."},
      {"q": "«No dic que calles, ___ que parles més baixet.»", "o": ["sinó", "si no", "sinó de"], "e": "Sinó (que, davant d'oració) té valor substitutiu. GNV 34.4.4."},
      {"q": "«Este hivern ha plogut prou; ___, encara hi ha sequera.»", "o": ["no obstant això", "per consegüent", "igualment"], "e": "No obstant això, tanmateix, amb tot o això no obstant introduïxen un contrast pròxim a la concessió. GNV 34.4.4; DNV."},
      {"q": "«Li ho vaig contar en confiança i, ___, ho ha xarrat a tot el món.»", "o": ["tanmateix", "per consegüent", "així mateix"], "e": "Tanmateix és un connectiu d'oposició. GNV 27.8, taula 27.7."},
      {"q": "«Has de fer el treball; ___, podries suspendre.» Escriu el connectiu que significa 'de no ser així'.", "a": ["altrament"], "e": "Altrament funciona com a connectiu de contrast ('si no, de no ser així'). GNV 34.4.4."},
      {"q": "«Estic d'acord amb tu en les idees fonamentals; ___, caldria matisar algunes qüestions.»", "o": ["ara bé", "per tant", "així mateix"], "e": "Ara bé és locució conjuntiva que introduïx una matisació després d'un punt acceptat del raonament (DNV, ara)."},
      {"q": "«Du una vida sana; ___, té bona salut.»", "o": ["per consegüent", "tanmateix", "altrament"], "e": "Per consegüent i consegüentment són connectius de conseqüència. GNV 27.8."},
      {"q": "«Recordem, ___, que no es pot fumar.»", "o": ["igualment", "tanmateix", "per consegüent"], "e": "Igualment, paral·lelament i així mateix són connectius d'equiparació. GNV 27.8."},
      {"q": "«___ ens va parlar d'economia, i després de cultura.»", "o": ["Primerament", "Tanmateix", "Altrament"], "e": "Primerament, segonament, finalment... ordenen la distribució del discurs. GNV 27.8."},
      {"q": "Quina de les conjuncions NO és concessiva?", "o": ["com siga que", "per bé que", "ni que"], "e": "Com siga que és causal; per bé que, ni que, si bé, bé que, mal que i per més que són concessives. GNV 34.5.3 i 34.5.4."},
      {"q": "«No pense dir-ho ___ em maten.»", "o": ["ni que", "per tal que", "sinó que"], "e": "Ni que és una conjunció concessiva: ni que em maten. GNV 34.5.3."},
      {"q": "«___ s'ha moderat, continua sent molt impulsiva.»", "o": ["Per bé que", "Per tal com", "Així que"], "e": "Per bé que és concessiva ('encara que'). GNV 34.5.3."},
      {"q": "«Se'n va anar a Suïssa, ___ els pares no volien.»", "o": ["malgrat que", "per tal que", "a mesura que"], "e": "Malgrat que és concessiva, igual que a pesar que. GNV 34.5.3."},
      {"q": "«___ tenia febra, va anar a la reunió.»", "o": ["Tot i que", "Per tal que", "Així que"], "e": "Tot i que és una conjunció concessiva. GNV 34.5.3."},
      {"q": "«___ s'enfade, no li pense deixar el cotxe.»", "o": ["Mal que", "Per tal que", "Ja que"], "e": "Mal que és concessiva ('encara que'). GNV 34.5.3."},
      {"q": "«___ les normes s'han de complir, hi ha una certa permissivitat.»", "o": ["Si bé", "Sinó que", "Tal com"], "e": "Si bé és una conjunció concessiva. GNV 34.5.3."},
      {"q": "«Ens han fet el descompte ___ no portàvem el carnet.»", "o": ["a pesar que", "per tal com", "a mesura que"], "e": "A pesar que (o malgrat que) és concessiva. GNV 34.5.3."},
      {"q": "«Es preveu una gran assistència, ___ se n'ha fet molta publicitat.»", "o": ["donat que", "si bé", "ni que"], "e": "Donat que és una conjunció causal, com atés que o vist que. GNV 34.5.4."},
      {"q": "«___ que no recorda res, no seré jo qui li ho diga.»", "o": ["Vist", "Mentre", "Jatsia"], "e": "Vist que és una conjunció causal. GNV 34.5.4."},
      {"q": "«Pots vindre ___ vullgues.»", "o": ["sempre que", "mentre que", "així com"], "e": "Sempre que, cada vegada que i tota vegada que expressen freqüència. GNV 34.5.7."},
      {"q": "«Cal enviar les inscripcions ___ es puga.»", "o": ["tan prompte com", "tan prompte que", "així com"], "e": "La locució temporal de posterioritat és tan prompte com (també així que, tan bon punt). GNV 34.5.7."},
      {"q": "Quina de les conjuncions expressa posterioritat immediata?", "o": ["tan bon punt", "ni que", "per bé que"], "e": "Tan bon punt, així que, tot seguit que, a penes... indiquen posterioritat immediata. GNV 34.5.7."},
      {"q": "«Escolta música ___ estudia.»", "o": ["alhora que", "a l'hora que", "mentre que"], "e": "Alhora que és la conjunció de simultaneïtat; mentre que és adversativa. GNV 34.5.7."},
      {"q": "«No és tan fàcil ___ m'havies dit.»", "o": ["com", "que", "com a"], "e": "En la comparativa d'igualtat (tan... com) la subordinada va introduïda per com. GNV 34.5.8."},
      {"q": "«El xiquet dorm menys ___ la xiqueta.»", "o": ["que", "com", "de"], "e": "En la comparativa de desigualtat (menys, més) s'usa que. GNV 34.5.8."},
      {"q": "«Digues-li-ho ___ no passara res.»", "o": ["com si", "com que", "així com"], "e": "Com si introduïx una subordinada modal comparativa i du subjuntiu imperfet. GNV 34.5.8."},
      {"q": "«Ho farem ___ que ens ajude ningú.» Escriu la preposició que forma la locució conjuntiva modal.", "a": ["sense"], "e": "Sense que introduïx una subordinada modal. GNV 34.5.8."}
    ]
  },
  {
    "id": "2366568e-86a8-5684-bfc5-f39606c60708", "type": "c2_mor_concordanca_temporal", "sort_order": 14,
    "title": "Concordança temporal i modes", "name": "Concordança de temps en temporals, condicionals i completives; indicatiu amb adverbis de dubte; ús coherent de les formes verbals",
    "content": "Concordança de temps en temporals, condicionals i completives (Quan anirem/anem..., Si no parlares, entendries...), indicatiu i no subjuntiu amb els adverbis de dubte, i ús coherent de les formes verbals en el text (3.2.2).", "icon": "⏳", "color": "#F3E5F5",
    "exercises": [
      {"q": "Quina afirmació és correcta sobre «Quan acabarem / acabem la faena, ja farem un viatge»?", "o": ["Les dos formes són acceptables: el futur és el més tradicional, però hui és més habitual el present de subjuntiu.", "Només és correcta la del futur.", "Només és correcta la del present d'indicatiu."], "e": "El present de subjuntiu alterna amb el futur en les temporals que designen situacions posteriors a l'acte de parla. GNV 28.5.a."},
      {"q": "«Si no ___, entendries l'explicació.»", "o": ["parlares", "parlaries", "parlaràs"], "e": "En la pròtasi d'una condicional irreal s'usa l'imperfet de subjuntiu, i en l'apòdosi el condicional: si no parlares, entendries. GNV 34.5.2."},
      {"q": "«Si ___ tot, me n'aniria d'acampada amb els amics.» (ell)", "o": ["ho aprovara", "ho aprovaria", "ho aprove"], "e": "En una condicional irreal la pròtasi porta imperfet de subjuntiu i l'apòdosi condicional. GNV 34.5.2, taula 34.2."},
      {"q": "«Si ho haguera aprovat tot, me n'___ anat d'acampada.»", "o": ["hauria", "haguera", "havia"], "e": "En la irreal de passat, la pròtasi du plusquamperfet de subjuntiu i l'apòdosi condicional perfet. GNV 34.5.2, taula 34.2."},
      {"q": "«Si no ___ a temps, avisa'm.»", "o": ["arribes", "arribares", "arribaràs"], "e": "En la condicional real, la pròtasi porta present (d'indicatiu o de subjuntiu) i l'apòdosi futur o imperatiu. GNV 34.5.2."},
      {"q": "«Si ho ___ tot, me n'iré d'acampada amb els amics.» (jo)", "o": ["aprove", "aprovara", "aprovaria"], "e": "Condicional real: present en la pròtasi i futur en l'apòdosi. GNV 34.5.2, taula 34.2."},
      {"q": "Quina és la forma genuïna?", "o": ["Potser era lleig, però tenia un atractiu especial.", "Potser fora lleig, però tenia un atractiu especial.", "Potser siga lleig, però tenia un atractiu especial."], "e": "Amb potser, possiblement i tal vegada, el mode tradicional és l'indicatiu; el subjuntiu és una innovació no genuïna. GNV 28.5.c."},
      {"q": "«Potser hui ___ el darrer dia.» Escriu el verb ser en present d'indicatiu (3a persona del singular).", "a": ["és"], "e": "Amb adverbis de dubte s'usa l'indicatiu, no el subjuntiu: Potser hui és el darrer dia (*Potser hui siga...). GNV 28.5.c."},
      {"q": "«Tal vegada ___ raó ells!»", "o": ["tenien", "tingueren", "tinguen"], "e": "Els adverbis de dubte demanen l'indicatiu: tal vegada tenien raó. GNV 28.5.c."},
      {"q": "Quina oració evita el subjuntiu no genuïn amb un adverbi de dubte?", "o": ["Segurament vindrà demà.", "Segurament vinga demà.", "Segurament vinguera demà."], "e": "Els adverbis modals de dubte o probabilitat (potser, possiblement, segurament...) es construïxen amb indicatiu. GNV 27.7.1 i 28.5.c."},
      {"q": "«Possiblement ___ demà.» Escriu el verb arribar en indicatiu (3a persona del plural).", "a": ["arribaran", "arriben"], "e": "Possiblement va amb indicatiu: possiblement arribaran demà (el present també pot tindre valor de futur). GNV 28.5.c."},
      {"q": "Quin matís aporta l'indicatiu en «Temien que ho perdrien tot»?", "o": ["Emfatitza la creença que ocorrerà.", "Expressa el desig que no ocórrega.", "Expressa irrealitat."], "e": "Amb verbs de temor, l'indicatiu emfatitza la creença i el subjuntiu el desig que no ocórrega. GNV 28.5.b."},
      {"q": "«Tinc por que ___.» Escriu pedregar en futur (3a persona del singular) per a emfatitzar la creença.", "a": ["pedregarà"], "e": "Amb verbs de temor l'indicatiu emfatitza la creença: Tinc por que pedregarà. GNV 28.5.b."},
      {"q": "«Tenia por que no es casara» és ambigua fora de context. Per què?", "o": ["Perquè el no pot ser expletiu o plenament negatiu.", "Perquè casara no és subjuntiu.", "Perquè la completiva ha d'anar sempre en indicatiu."], "e": "El no expletiu era general en la llengua antiga; hui pot significar tant 'que es casara' com 'que no es casara'. GNV 28.5.b, observació."},
      {"q": "«Temia que no ___ a temps.»", "o": ["arribara", "arribe", "haja arribat"], "e": "Amb el verb principal en passat (temia) la completiva porta imperfet de subjuntiu. GNV 28.4.2.b."},
      {"q": "«Vol que demà ___ puntuals.»", "o": ["arribem", "arribàrem", "hàgem arribat"], "e": "El present de subjuntiu assumix els valors de present i de futur, ací posterioritat: vol que demà arribem. GNV 28.4.2.a."},
      {"q": "«Volia que ___ l'endemà.»", "o": ["tornàrem", "tornem", "haguérem tornat"], "e": "El verb principal en passat demana imperfet de subjuntiu en la subordinada: volia que tornàrem. GNV 28.4.2.b."},
      {"q": "«Volia que ___ l'endemà.» Escriu tornar en imperfet de subjuntiu (1a persona del plural).", "a": ["tornàrem"], "e": "Imperfet de subjuntiu de la 1a conjugació: tornara, tornares, tornara, tornàrem, tornàreu, tornaren. GNV 28.4.2.b."},
      {"q": "«Li molestava que ___ dormint.»", "o": ["estigueren", "estiguen", "estaren"], "e": "Amb el verb principal en passat, la completiva porta imperfet de subjuntiu (simultaneïtat en el passat): li molestava que estigueren dormint. GNV 28.4.2.b."},
      {"q": "«És possible que ja se n'___ anat.»", "o": ["hagen", "hagueren", "hauran"], "e": "Perfet de subjuntiu, paral·lel al perfet d'indicatiu: és possible que se n'hagen anat. GNV 28.4.2.c."},
      {"q": "«El preocupava que no li ___ dit res.»", "o": ["hagueren", "hagen", "havien"], "e": "Amb el verb principal en passat, el plusquamperfet de subjuntiu equival al plusquamperfet d'indicatiu: no li havien dit. GNV 28.4.2.c."},
      {"q": "«El preocupava que no li ___ dit res.» Escriu haver en imperfet de subjuntiu (3a persona del plural).", "a": ["hagueren"], "e": "El plusquamperfet de subjuntiu es forma amb l'imperfet de subjuntiu d'haver: hagueren dit. GNV 28.4.2.c."},
      {"q": "«Li vaig dir que quan ___ fet els deures se'n vinguera a jugar.»", "o": ["haguera", "haja", "hauria"], "e": "En el context de passat, la temporal futura ix en plusquamperfet de subjuntiu: quan haguera fet. GNV 28.4.2.c."},
      {"q": "«Va dir que era probable que ja se n'___ anat quan arribaríem.»", "o": ["hagueren", "hagen", "hauran"], "e": "En el context de passat, el plusquamperfet de subjuntiu (hagueren) equival al condicional perfet (haurien). GNV 28.4.2.c."},
      {"q": "Quina oració equival a «Va dir que els qui arribarien primer s'encarregarien de tot»?", "o": ["Va dir que els qui arribaren primer s'encarregarien de tot.", "Va dir que els qui arriben primer s'encarregarien de tot.", "Va dir que els qui arribaran primer s'encarregarien de tot."], "e": "En contextos de posterioritat en el passat, l'imperfet de subjuntiu alterna amb el condicional. GNV 28.5.a."},
      {"q": "«Ens va assegurar que l'endemà ___ la carta.»", "o": ["enviaria", "enviarà", "haja enviat"], "e": "Amb un verb principal en passat, la posterioritat s'expressa amb condicional: l'endemà enviaria. GNV 28.4.1."},
      {"q": "«Em va dir que se n'___ l'endemà de viatge.»", "o": ["anaven", "anem", "aniran"], "e": "L'imperfet pot tindre valor de futur de passat: Em va dir que se n'anaven l'endemà. GNV 28.4.1.b, taula 28.7."},
      {"q": "«Així que ___ Conxa, ens n'anirem.»", "o": ["arribe", "arribava", "va arribar"], "e": "Amb conjuncions temporals de posterioritat que designen una situació futura s'usa el present de subjuntiu (o el futur). GNV 34.5.7 i 28.5.a."},
      {"q": "«Tan bon punt ___, vam començar la reunió.»", "o": ["va arribar", "arribe", "arribarà"], "e": "Amb un fet ja passat, la temporal porta passat: tan bon punt va arribar (o arribà). GNV 34.5.7."},
      {"q": "«Abans que li ho ___, ja ho havia fet.»", "o": ["demanara", "demane", "demanarà"], "e": "Amb el verb principal en passat, la temporal introduïda per abans que va en imperfet de subjuntiu. GNV 34.5.7."},
      {"q": "«Et faré companyia fins que ___ el teu fill.»", "o": ["arribe", "arribara", "haguera arribat"], "e": "Amb fins que referit al futur s'usa el present de subjuntiu. GNV 34.5.7."},
      {"q": "«Quan ___ els deures, vine a jugar.»", "o": ["hages fet", "hagueres fet", "has fet"], "e": "Per a una acció acabada abans d'una altra futura s'usa el perfet de subjuntiu: quan hages fet. GNV 28.4.2.c."},
      {"q": "«Espere que t'ho ___ passat molt bé.»", "o": ["hages", "has", "haguessis"], "e": "Els verbs de desig o voluntat demanen subjuntiu, i el perfet de subjuntiu és hages passat. GNV 34.5.1.1."},
      {"q": "«Preguem als senyors viatgers que es ___ al tren.»", "o": ["dirigisquen", "dirigixen", "dirigiran"], "e": "Amb verbs de petició o de voluntat la completiva va en subjuntiu; la conjunció que no s'elidix. GNV 34.5.1.1."},
      {"q": "«Pots demanar un certificat en cas que el ___.»", "o": ["necessites", "necessitaràs", "necessitaries"], "e": "La locució condicional en cas que es construïx amb subjuntiu. GNV 34.5.2."},
      {"q": "«Posat que ___, farem festa.» Escriu vindre en present de subjuntiu (3a persona del singular).", "a": ["vinga"], "e": "Posat que és una conjunció condicional i demana subjuntiu. GNV 34.5.2."},
      {"q": "«T'ho contaré sempre que no et ___.»", "o": ["rigues", "ris", "riuràs"], "e": "Sempre que amb valor condicional demana present de subjuntiu: sempre que no et rigues. GNV 34.5.2."},
      {"q": "«Amb que Neus ___, tot s'aclarirà.»", "o": ["parle", "parlarà", "parlaria"], "e": "La conjunció condicional amb que va seguida de subjuntiu. GNV 34.5.2."},
      {"q": "Quin valor té el futur en «No les molesteu, que ja estaran dormint»?", "o": ["Probabilitat", "Posterioritat", "Obligació"], "e": "El futur de probabilitat apareix sobretot amb ser, estar i tindre i en el futur perfet. GNV 28.4.1.c."},
      {"q": "«Ja se'n ___ haver anat.» (probabilitat; opció més general en registres formals)", "o": ["deuen", "poden", "han"], "e": "La perífrasi «deure + infinitiu» expressa probabilitat i és més habitual en els registres formals. GNV 28.4.1.c."},
      {"q": "«Ja se'n ___ haver anat.» Escriu el verb de la perífrasi de probabilitat (3a persona del plural).", "a": ["deuen"], "e": "Deure + infinitiu expressa probabilitat: ja se'n deuen haver anat. GNV 28.4.1.c."},
      {"q": "«Dos anys més tard publicarà la seua obra mestra.» Quin és el valor del futur?", "o": ["Futur dels historiadors (fet passat posterior a un altre)", "Probabilitat", "Sorpresa"], "e": "El futur pot referir-se a fets passats ocorreguts després d'un altre, sobretot en textos històrics o biogràfics. GNV 28.4.1.c."},
      {"q": "Quina oració és correcta quan el subjecte de les dos oracions és el mateix?", "o": ["Lamente haver-me enfadat.", "Lamente que m'he enfadat.", "Lamente que m'enfade."], "e": "Quan la completiva té el verb en infinitiu no s'usa la conjunció: Lamente haver-me enfadat (Lamente que t'hages enfadat). GNV 34.5.1.2."},
      {"q": "«Si ho ___ tot, me n'aniria d'acampada.» Escriu aprovar en imperfet de subjuntiu (3a persona del singular).", "a": ["aprovara"], "e": "Pròtasi irreal: imperfet de subjuntiu (aprovara) i condicional en l'apòdosi. GNV 34.5.2."}
    ]
  },
  {
    "id": "280b4a90-26ba-5eef-9c6b-ad07be408040", "type": "c2_mor_verbs_formes_no_personals", "sort_order": 15,
    "title": "Verbs defectius i formes no personals", "name": "Verbs defectius (caldre, haver-hi, meteorològics: nevar, ploure, plovisquejar, gotinyar); infinitiu de recapitulació; gerundi incorrecte; règims dels verbs coordinats",
    "content": "Verbs defectius (caldre, haver-hi, meteorològics), infinitiu de recapitulació incorrecte, gerundi incorrecte consecutiu, copulatiu i especificatiu i les alternatives, i règims dels verbs coordinats (3.2.2).", "icon": "🌧️", "color": "#E8F5E9",
    "exercises": [
      {"q": "Quina oració amb el verb ploure, en sentit literal, és correcta?", "o": ["Ha plogut molts dies seguits.", "Han plogut molts dies seguits.", "Plouen molts dies seguits."], "e": "Els verbs meteorològics són impersonals: no tenen subjecte i només s'usen en 3a persona del singular (Plou molt. Ha pedregat tota la nit). GNV 8.5."},
      {"q": "Quina de les oracions conté un verb impersonal?", "o": ["És molt tard.", "Els meus cosins passegen cada dia.", "El president parlarà demà."], "e": "Són impersonals els verbs meteorològics i expressions com és tard, mancats de subjecte (Plou molt. Ha pedregat tota la nit. És molt tard). GNV 8.5."},
      {"q": "Què vol dir «Hui plovisqueja»?", "o": ["Plou de forma lleugera, a gotes menudes.", "Cau pedra.", "Plou amb molta força."], "e": "Plovisquejar és 'ploure de forma lleugera, a gotes menudes i nombroses' (DNV)."},
      {"q": "Escriu l'infinitiu del verb meteorològic que és sinònim de plovisquejar (comença per got-).", "a": ["gotinyar"], "e": "El DNV defineix gotinyar com un verb meteorològic sinònim de plovisquejar."},
      {"q": "Què significa el verb meteorològic «pedregar» en «Han dit que a la vesprada pedregarà»?", "o": ["Caure pedra", "Caure neu", "Caure rosada"], "e": "El DNV registra pedregar com a verb intransitiu meteorològic: 'caure pedra'."},
      {"q": "«Demà ___ a la serra.» Escriu nevar en futur (3a persona del singular).", "a": ["nevarà"], "e": "Nevar és un verb meteorològic impersonal ('caure neu', DNV); només s'usa en 3a persona del singular."},
      {"q": "«Que ___ i que neve.» Escriu ploure en present de subjuntiu (3a persona del singular).", "a": ["ploga"], "e": "El DNV registra l'expressió que ploga i que neve, amb el subjuntiu ploga."},
      {"q": "«Ha ___ molt este hivern.» Escriu el participi de ploure.", "a": ["plogut"], "e": "El participi de ploure és plogut (ha plogut), invariable en l'ús impersonal."},
      {"q": "Quin és el caràcter gramatical del verb «caldre»?", "o": ["Verb impersonal, sense subjecte", "Verb pronominal", "Verb copulatiu"], "e": "El verb caldre és impersonal (GNV 6.2.2): cal que ens comuniqueu el resultat. GNV 31.3."},
      {"q": "Quina de les expressions d'obligació NO és acceptable?", "o": ["Hi ha que comunicar el resultat.", "Cal comunicar el resultat.", "S'ha de comunicar el resultat."], "e": "No són acceptables hi ha que ni tindre que; sí caldre, haver de i, poc usat, tindre de. GNV 31.3."},
      {"q": "Quina d'estes perífrasis d'obligació és acceptable?", "o": ["Has d'aprofitar més el temps.", "Tens que aprofitar més el temps.", "Hi ha que aprofitar més el temps."], "e": "La perífrasi «haver de + infinitiu» expressa obligació; tindre que i hi ha que no són acceptables. GNV 31.3."},
      {"q": "«No cal que ___ a la reunió.» Escriu el verb anar en present de subjuntiu (2a persona del singular).", "a": ["vages"], "e": "El DNV exemplifica caldre amb «No cal que vages»: caldre + que + subjuntiu."},
      {"q": "«Si fas les coses ___, ningú et podrà retraure res.»", "o": ["com cal", "com cala", "com caldrà"], "e": "Com cal és la locució adverbial de 'com ha de ser una cosa' (DNV, caldre)."},
      {"q": "Segons la GNV, en registres formals amb el verb haver-hi és més adequada...", "o": ["la manca de concordança: hi ha més cadires", "la concordança: hi han més cadires", "cap de les dos formes"], "e": "El sintagma nominal de haver-hi funciona com a complement directe; les dos formes són acceptables, però en registres formals es preferix la tradicional sense concordança. GNV 32.2.d."},
      {"q": "Quina funció fa el sintagma nominal «més cadires» en «A ma casa hi ha més cadires»?", "o": ["Complement directe", "Subjecte", "Complement de règim"], "e": "El verb impersonal haver-hi no té subjecte; el sintagma que l'acompanya es comporta com un complement directe. GNV 32.2.d."},
      {"q": "Quina és la formulació correcta?", "o": ["Per a concloure, hem de dir que estem molt satisfets de la participació.", "Per a concloure, dir que estem molt satisfets de la participació.", "Per a concloure, dient que estem molt satisfets de la participació."], "e": "No és recomanable l'infinitiu com a verb principal amb valor de recapitulació; s'usa hem de dir, cal dir, direm... GNV 28.6.2.a."},
      {"q": "«Per a concloure, ___ que estem molt satisfets de l'alta participació.»", "o": ["cal dir", "dir", "dient"], "e": "L'infinitiu sol de recapitulació és innovació no recomanable; es resol amb cal dir, hem de dir o direm. GNV 28.6.2.a."},
      {"q": "Quina és la formulació correcta d'una ordre o prohibició?", "o": ["Tanqueu bé la porta després d'eixir.", "Tancar bé la porta després d'eixir.", "Tancant bé la porta després d'eixir."], "e": "Per a ordes i prohibicions no s'ha d'usar l'infinitiu tot sol: Tanqueu bé la porta; Es prohibix fumar (no *No fumar). GNV 28.6.2.a, observació."},
      {"q": "Quina és la formulació correcta d'una prohibició escrita?", "o": ["Es prohibix fumar.", "No fumar.", "Fumant prohibit."], "e": "Es prohibix fumar (o Prohibit fumar) és la fórmula correcta; no s'usa l'infinitiu tot sol. GNV 28.6.2.a, observació."},
      {"q": "Quin valor té l'infinitiu en «A dormir, que ja és tardíssim»?", "o": ["Imperatiu", "Recapitulatiu", "Consecutiu"], "e": "Precedit de a, l'infinitiu pot tindre valor imperatiu: A callar he dit! A dormir. GNV 28.6.2.a."},
      {"q": "Quina oració evita la substantivació de l'infinitiu amb l'article?", "o": ["Conéixer bé diferents llengües l'ha ajudat a aconseguir el treball.", "El conéixer bé diferents llengües l'ha ajudat a aconseguir el treball.", "Al conéixer bé diferents llengües l'ha ajudat a aconseguir el treball."], "e": "En la llengua més general convé evitar l'infinitiu substantivat amb article: s'usa l'infinitiu simple, el fet de o un substantiu. GNV 28.6.2.b."},
      {"q": "Quin és el plural de «dinar» com a substantiu?", "o": ["dinars", "dinares", "dinar (invariable)"], "e": "Dinar, sopar, berenar, ser, parlar... són infinitius convertits en substantius i admeten la flexió de nombre: un dinar, uns dinars. GNV 28.6.2.b."},
      {"q": "«En un ___ d'ulls va acabar el treball.»", "o": ["batre", "batent", "batut"], "e": "L'infinitiu substantivat apareix en locucions com en un batre d'ulls o en un tancar i obrir d'ulls. GNV 28.6.2.b."},
      {"q": "Quina oració evita el gerundi amb valor consecutiu?", "o": ["Va caure i es va trencar la cama.", "Va caure trencant-se la cama.", "Va caure i trencant-se la cama."], "e": "El gerundi expressa simultaneïtat; no es pot usar per a la conseqüència posterior d'un fet. GNV 28.6.2.c."},
      {"q": "Com s'evita el gerundi consecutiu en «*Va ploure tota la nit, inundant els carrers»?", "o": ["Va ploure tota la nit i es van inundar els carrers.", "Va ploure tota la nit, inundant els carrers.", "Va ploure tota la nit inundant-se els carrers."], "e": "El gerundi no pot expressar la conseqüència posterior: es coordina amb i. GNV 28.6.2.c."},
      {"q": "Quina és la correcció de «*No presentà el certificat en el termini fixat, sent desqualificat»?", "o": ["No presentà el certificat en el termini fixat i per això fon desqualificat.", "No presentà el certificat en el termini fixat, essent desqualificat.", "No presentà el certificat en el termini fixat, havent sigut desqualificat."], "e": "El gerundi consecutiu es substituïx per una oració coordinada amb i per això o per la qual cosa. GNV 28.6.2.c; Quadern C2."},
      {"q": "Quina oració evita el gerundi especificatiu?", "o": ["El Govern ha aprovat un decret que regula els estudis universitaris.", "El Govern ha aprovat un decret regulant els estudis universitaris.", "El Govern ha aprovat un decret regulat els estudis universitaris."], "e": "El gerundi no pot modificar un substantiu amb valor de relatiu especificatiu: s'usa que regula. GNV 28.6.2.d."},
      {"q": "Com s'evita el gerundi especificatiu en «*Hem rebut un escrit resumint els acords»?", "o": ["Hem rebut un escrit que resumix els acords.", "Hem rebut un escrit resumint els acords.", "Hem rebut un escrit, resumint, els acords."], "e": "El gerundi no pot funcionar com a relatiu especificatiu: es resol amb una oració de relatiu (que resumix). GNV 28.6.2.d."},
      {"q": "«Vos enviem una carta ___ vos informem sobre les noves condicions.» (en lloc de *informant sobre...)", "o": ["en què", "a què", "per què"], "e": "El gerundi especificatiu se substituïx per un relatiu (en què, en la qual) o per una final (per a informar). Quadern C2; GNV 28.6.2.d."},
      {"q": "En quina oració és correcte l'ús del gerundi?", "o": ["Se'n va anar cridant.", "Va caure trencant-se la cama.", "Va aprovar un decret regulant els estudis."], "e": "El gerundi és adequat per a la simultaneïtat o la manera (se'n va anar cridant). GNV 28.6.1 i 28.6.2."},
      {"q": "Amb quins substantius pot el gerundi funcionar com a modificador de manera («Les paraules del president encoratjant els jugadors»)?", "o": ["Deverbals i de percepció o comunicació (entrada, imatge, carta, paraula...)", "Qualsevol substantiu", "Només els substantius abstractes"], "e": "S'admet amb determinats substantius deverbals i de percepció, comunicació o parts del cos. GNV 28.6.2.d, observació."},
      {"q": "Quina forma de gerundi NO és acceptable?", "o": ["diguent", "dient", "venint"], "e": "No és acceptable cap gerundi amb increment velar (-guent, -quent): diguent, vinguent, visquent → dient, venint, vivint. GNV 30.2.3, observació."},
      {"q": "Escriu el gerundi del verb dir.", "a": ["dient"], "e": "El gerundi de dir és dient (no *diguent). GNV 30.2.3, observació."},
      {"q": "Escriu el gerundi del verb vindre.", "a": ["venint"], "e": "El gerundi de vindre és venint (no *vinguent). GNV 30.2.3, observació."},
      {"q": "Escriu el gerundi del verb viure.", "a": ["vivint"], "e": "El gerundi de viure és vivint (no *visquent). GNV 30.2.3, observació."},
      {"q": "Escriu el gerundi del verb beure.", "a": ["bevent"], "e": "El gerundi de beure és bevent (no *beguent). GNV 30.2.3."},
      {"q": "Quina forma exigix un nexe per a indicar anterioritat?", "o": ["L'infinitiu: després d'haver analitzat el tema", "El gerundi: havent analitzat el tema", "El participi: analitzat el tema"], "e": "L'infinitiu compost no pot usar-se sense nexe que n'oriente el valor d'anterioritat, però el gerundi compost sí. GNV 28.6.1."},
      {"q": "Quina oració és correcta?", "o": ["Havent analitzat el tema, no hem arribat a cap solució.", "Haver analitzat el tema, no hem arribat a cap solució.", "Haguent analitzat el tema, no hem arribat a cap solució."], "e": "El gerundi compost indica anterioritat sense nexe; l'infinitiu compost necessita nexe (després d'haver analitzat). GNV 28.6.1."},
      {"q": "Quin valor aspectual té el gerundi en «Preparant el sopar em vaig recordar del que t'havia promés»?", "o": ["Imperfectiu: simultaneïtat amb l'acció principal", "Perfectiu: anterioritat acabada", "Posterioritat"], "e": "El gerundi és una forma imperfectiva i expressa situacions en curs o simultànies. GNV 28.6.1.a."},
      {"q": "Quin valor té el participi en «Acabada la reunió, vam eixir a sopar»?", "o": ["Perfectiu: situació anterior i acabada", "Imperfectiu: situació en curs", "Posterioritat"], "e": "El participi és una forma perfectiva que fa referència a situacions anteriors i acabades. GNV 28.6.1.b."},
      {"q": "Què indica l'infinitiu en «—Què has fet? —Parlar per telèfon amb la mare»?", "o": ["Una situació d'anterioritat acabada", "Una situació en curs", "Una situació posterior"], "e": "L'infinitiu és una forma no marcada: el seu valor depén del context. GNV 28.6.1.c."},
      {"q": "Quina és la formulació correcta de «*Llig i parle d'un llibre»?", "o": ["Llig un llibre i en parle.", "Llig i parle d'un llibre.", "Llig d'un llibre i parle."], "e": "Dos verbs coordinats que regixen preposicions diferents no poden compartir el complement: Llig un llibre i en parle (Quadern C2; cf. GNV 26.7.1)."},
      {"q": "Quina oració és correcta pel que fa al règim dels verbs coordinats?", "o": ["Ha apel·lat contra la sentència i ha insistit en la seua innocència.", "Ha apel·lat i insistit en la sentència.", "Ha apel·lat i insistit contra la sentència."], "e": "Apel·lar demana contra i insistir demana en: cada verb ha de portar el seu complement. GNV 32.4, taula 32.1."}
    ]
  },
  {
    "id": "6c5f3a6e-146f-54b6-ac3b-45c777e90d5d", "type": "c2_mor_morfologia_verbal", "sort_order": 16,
    "title": "Morfologia verbal: formes excepcionals i registres", "name": "Formes diferenciades (cuit/cogut, sigut, ser/ésser), incoatius, passat simple i imperfet de subjuntiu forts, participis irregulars i dobles (complit, imprés, absolt...)",
    "content": "Formes verbals diferenciades per significat (cuit/cogut), per varietat (sigut) o arcaiques (ésser), incoatius en -ix-/-eix-, formes formals del passat simple, de l'imperfet de subjuntiu (-ara/-era/-és) i participis irregulars (imprés, absolt, complit...) (3.2.2).", "icon": "🔡", "color": "#FCE4EC",
    "exercises": [
      {"q": "«Ahir vaig ___ l'arròs amb marisc.» Quin és el participi adequat de coure en este sentit?", "o": ["cuit", "cogut", "coit"], "e": "Coure admet el participi fort cuit i el regular cogut, amb diferències de significat: He cuit l'arròs (Quadern C2; GNV 30.2.4.4)."},
      {"q": "«M'ha ___ la ferida tot el dia.» (sensació de coïssor)", "o": ["cogut", "cuit", "coit"], "e": "Amb el sentit de 'produir una sensació dolorosa semblant a la d'una cremada' s'usa el participi regular: M'ha cogut la ferida (Quadern C2; DNV, coure 8; GNV 30.2.4.4)."},
      {"q": "«La proposta de llei ha ___ molt criticada pels grups ecologistes.»", "o": ["sigut", "segut", "sido"], "e": "El DNV exemplifica el participi de ser amb ha sigut; segut és el de seure i sido és castellanisme. GVB 15.6.1."},
      {"q": "Quin infinitiu és la forma arcaica o culta de «ser»?", "o": ["ésser", "eixir", "estar"], "e": "El DNV remet ésser a ser; ser és la forma general actual i ésser, l'arcaica. GNV 29.5; Quadern C2."},
      {"q": "«Nosaltres ___ el dinar a les dos.» (servir, present d'indicatiu)", "o": ["servim", "servixem", "serveixem"], "e": "Les persones 4 i 5 del present d'indicatiu dels incoatius no porten increment: servim, serviu. GNV 29.5.e."},
      {"q": "«Vosaltres ___ el cafè en la terrassa.» (servir, present d'indicatiu)", "o": ["serviu", "servixeu", "serveixeu"], "e": "En la 5a persona del present d'indicatiu no hi ha increment incoatiu: servim, serviu. GNV 29.5.e."},
      {"q": "Quina forma del present de subjuntiu de servir se sent com a antiga i molt formal?", "o": ["servesca", "servisca", "servisquen"], "e": "Les formes amb e en -sc- (servesc, servesca, servesques) se senten com a antigues i molt formals; en l'estàndard s'evita. GNV 29.5.e, observació."},
      {"q": "Quina és una variant escrita acceptable de «servix»?", "o": ["serveix", "servisc", "serviu"], "e": "En la llengua escrita, servixes, servix i servixen alternen amb serveixes, serveix i serveixen. GNV 29.5.e."},
      {"q": "Quin és el participi de nàixer?", "o": ["nascut", "naixut", "naixcut"], "e": "En els verbs de la 2a conjugació amb -sc-, s'han generalitzat les formes amb s: nasc, nasca, nascut. GNV 29.5.e."},
      {"q": "Escriu el participi de créixer.", "a": ["crescut"], "e": "Créixer fa cresc, cresca, crescut. GNV 29.5.e."},
      {"q": "Escriu el participi de viure.", "a": ["viscut"], "e": "Viure fa visc, visca, viscut. GNV 29.5.e."},
      {"q": "Quin és el participi de comprendre?", "o": ["comprés", "comprengut", "comprendit"], "e": "Els verbs acabats en -ndre (excepte vendre i pondre) tenen participi sigmàtic: comprés, atés, empés. GNV 30.2.4.4.a."},
      {"q": "«Este llibre ha sigut ___ a València.» (imprimir)", "o": ["imprés", "imprimit", "imprimat"], "e": "Imprimir té participi fort en -s: imprés. GNV 30.2.4.4.a."},
      {"q": "Quin és el participi de vendre?", "o": ["venut", "vés", "vengut"], "e": "Vendre i pondre són excepcions entre els acabats en -ndre: vendre fa venut (regular) i pondre fa post. GNV 30.2.4.4.a i c."},
      {"q": "Quin és el participi d'atényer?", "o": ["atés", "atengut", "atenyit"], "e": "Atényer, empényer i espényer tenen participi sigmàtic: atés, empés, espés. GNV 30.2.4.4.a."},
      {"q": "Escriu el participi de cloure.", "a": ["clos"], "e": "Cloure fa participi sigmàtic: clos, closa. GNV 30.2.4.4.a."},
      {"q": "Escriu el participi de fondre.", "a": ["fos"], "e": "Fondre és el model del participi sigmàtic: fos, fosa, fosos, foses. GNV 30.2.4.4, taula 30.4."},
      {"q": "Quin és el participi de resoldre?", "o": ["resolt", "resolgut", "resost"], "e": "Els verbs acabats en -ldre tenen participi fort en -t: molt, absolt, resolt. GNV 30.2.4.4.b."},
      {"q": "«L'acusat ha sigut ___.» (absoldre)", "o": ["absolt", "absolgut", "absost"], "e": "Absoldre fa absolt, com resoldre fa resolt. GNV 30.2.4.4.b."},
      {"q": "Quin és el participi de doldre?", "o": ["dolgut", "dolt", "dolgit"], "e": "Oldre i doldre són excepcions dels acabats en -ldre: olgut i dolgut. GNV 30.2.4.4.b."},
      {"q": "Escriu el participi de traure.", "a": ["tret"], "e": "Traure té participi fort en -t, com dir (dit), dur (dut), escriure (escrit), fer (fet) i morir (mort). GNV 30.2.4.4.b."},
      {"q": "Escriu el participi de respondre.", "a": ["respost"], "e": "Tenen participi en -st pondre (post), respondre (respost), veure (vist) i riure (rist o rigut). GNV 30.2.4.4.c."},
      {"q": "Escriu el participi de pondre.", "a": ["post"], "e": "Pondre fa post (participi en -st). GNV 30.2.4.4.c."},
      {"q": "Quina és una forma acceptable del participi de riure?", "o": ["rigut", "riut", "rigit"], "e": "Riure té el participi rist, que també admet la forma regular rigut. GNV 30.2.4.4.c."},
      {"q": "Escriu el participi de cobrir.", "a": ["cobert"], "e": "Només obrir (obert) i cobrir (cobert) tenen participi en -ert. GNV 30.2.4.4.d."},
      {"q": "Quin és el participi de complir en valencià?", "o": ["complit", "complert", "cumplit"], "e": "En valencià, complir, establir, omplir i suplir adopten participis febles regulars: complit, establit... (complert és d'altres parlars). GNV 30.2.4.4, observació."},
      {"q": "Quin és el participi d'oferir en valencià?", "o": ["oferit", "ofert", "oferert"], "e": "Oferir fa participi feble: oferit (ofert pertany a altres parlars). GNV 30.2.4.4, observació."},
      {"q": "Quin és el participi de mantindre?", "o": ["mantingut", "mantés", "mantit"], "e": "Els derivats de tindre fan -ingut: mantingut, detingut; mantés i detés no són acceptables. GNV 30.2.4.4.a, observació."},
      {"q": "«Nosaltres ___ la faena en un dia.» (fer, passat simple)", "o": ["férem", "farem", "fem"], "e": "El passat simple fort de fer és fiu, feres, féu, férem, féreu, feren. GNV 30.2.4.3."},
      {"q": "«Ell ___ un gran poeta.» Escriu ser en passat simple (3a persona del singular).", "a": ["fou", "fon"], "e": "El passat simple de ser és fui, fores, fou (o fon), fórem, fóreu, foren. GNV 30.2.4.3."},
      {"q": "«Ells ___ els primers en arribar.» (ser, passat simple)", "o": ["foren", "fórem", "fores"], "e": "3a persona del plural del passat simple de ser: foren. GNV 30.2.4.3."},
